function formatCapturedAt(value: string) {
  const date = new Date(value);

  if (Number.isNaN(date.getTime())) {
    return value;
  }

  return new Intl.DateTimeFormat("en-GB", {
    dateStyle: "medium",
    timeStyle: "short",
  }).format(date);
}

// UK tax years run 6 April to 5 April; used to give tax records a relevant period label.
function ukTaxYearLabel(value: string) {
  const date = new Date(`${value}T00:00:00`);

  if (Number.isNaN(date.getTime())) {
    return "—";
  }

  const year = date.getFullYear();
  const isBeforeApril6 = date.getMonth() < 3 || (date.getMonth() === 3 && date.getDate() < 6);
  const startYear = isBeforeApril6 ? year - 1 : year;

  return `${startYear}/${String((startYear + 1) % 100).padStart(2, "0")} tax year`;
}

// Months are only "elapsed" (eligible for an end-of-month pay reminder) once they are strictly before the current calendar month.
function getElapsedTaxMonths(jobStartDate: string, referenceDate: Date) {
  const start = new Date(`${jobStartDate}T00:00:00`);
  const months: Array<{ year: number; month: number }> = [];

  if (Number.isNaN(start.getTime())) {
    return months;
  }

  let year = start.getFullYear();
  let month = start.getMonth();
  const currentYear = referenceDate.getFullYear();
  const currentMonth = referenceDate.getMonth();

  while (year < currentYear || (year === currentYear && month < currentMonth)) {
    months.push({ year, month });
    month += 1;
    if (month > 11) {
      month = 0;
      year += 1;
    }
  }

  return months;
}

function isSameTaxMonth(payPeriod: string, year: number, month: number) {
  return payPeriod === `${year}-${String(month + 1).padStart(2, "0")}`;
}

// Backfills payPeriod on tax payment records saved before that field existed, using the "<Month> <Year>" text in the description.
function inferPayPeriodFromDescription(description: string) {
  const monthNames = ["january", "february", "march", "april", "may", "june", "july", "august", "september", "october", "november", "december"];
  const match = description.toLowerCase().match(/(january|february|march|april|may|june|july|august|september|october|november|december)\s+(\d{4})/);

  if (!match) {
    return "";
  }

  const monthIndex = monthNames.indexOf(match[1]);
  return `${match[2]}-${String(monthIndex + 1).padStart(2, "0")}`;
}

// Cash snapshot dates are calendar days; accepts legacy ISO datetime values and returns "" when unusable.
function normaliseCashSnapshotDate(value: unknown) {
  if (typeof value !== "string") {
    return "";
  }

  const match = value.trim().match(/^(\d{4})-(\d{2})-(\d{2})(?:[T ].*)?$/);

  if (!match) {
    return "";
  }

  const [, year, month, day] = match;
  const parsed = new Date(Number(year), Number(month) - 1, Number(day));

  if (
    parsed.getFullYear() !== Number(year)
    || parsed.getMonth() !== Number(month) - 1
    || parsed.getDate() !== Number(day)
  ) {
    return "";
  }

  return `${year}-${month}-${day}`;
}

function formatCashSnapshotDate(value: string) {
  const normalised = normaliseCashSnapshotDate(value);

  if (!normalised) {
    return "";
  }

  const [year, month, day] = normalised.split("-").map(Number);

  return new Intl.DateTimeFormat("en-GB", { dateStyle: "medium" }).format(new Date(year, month - 1, day));
}

function formatSavedViewUpdatedAt(value?: string) {
  if (!value) {
    return "Updated date unavailable";
  }

  const updatedAt = new Date(value);
  if (Number.isNaN(updatedAt.getTime())) {
    return "Updated date unavailable";
  }

  const now = new Date();
  const elapsedMinutes = Math.floor((now.getTime() - updatedAt.getTime()) / (1000 * 60));
  if (elapsedMinutes < 1) {
    return "Updated just now";
  }

  if (elapsedMinutes < 60) {
    return `Updated ${elapsedMinutes} minutes ago`;
  }

  if (updatedAt.toDateString() === now.toDateString()) {
    return "Updated today";
  }

  return `Updated ${new Intl.DateTimeFormat("en-GB", {
    day: "numeric",
    month: "short",
    year: "numeric",
  }).format(updatedAt)}`;
}

function getStatusFromOutcome(outcome: ReviewOutcome) {
  if (outcome === "Close") {
    return "Closed";
  }

  if (outcome === "Keep as Capture") {
    return "Reviewed";
  }

  return "Converted";
}

function formatReviewOutcome(outcome: ReviewOutcome | null | undefined) {
  if (!outcome) {
    return null;
  }

  if (outcome === "Keep as Capture") {
    return "Capture";
  }

  return outcome.replace("Convert to ", "");
}

function getActionOwnerDisplay(action: ActionRecord, people: PersonRecord[]) {
  const activePerson = action.ownerPersonId
    ? people.find((person) => person.id === action.ownerPersonId && person.status === "Active")
    : null;

  if (activePerson) {
    return activePerson.name;
  }

  if (action.owner && action.owner.trim()) {
    return action.owner.trim();
  }

  return "Unassigned";
}

function getActionOwnerValue(action: ActionRecord, people: PersonRecord[]) {
  if (action.ownerPersonId) {
    const activeOwner = people.find((person) => person.id === action.ownerPersonId && person.status === "Active");
    if (activeOwner) {
      return activeOwner.id;
    }
  }

  const matchingActivePerson = people.find((person) =>
    person.status === "Active" && person.name.trim().toLowerCase() === (action.owner || "").trim().toLowerCase(),
  );

  return matchingActivePerson ? matchingActivePerson.id : "unassigned";
}

