function useFinanceSavedFeedback(): [boolean, () => void] {
  const [hasSaved, setHasSaved] = useState(false);

  useEffect(() => {
    if (!hasSaved) {
      return;
    }

    const timeoutId = window.setTimeout(() => setHasSaved(false), 1800);
    return () => window.clearTimeout(timeoutId);
  }, [hasSaved]);

  return [hasSaved, () => setHasSaved(true)];
}

const financeFieldClass = "w-full rounded-xl border border-[#beb3aa] bg-white px-3.5 py-3 text-[14px] text-[#171717] outline-none transition focus:border-[#171717] focus:ring-3 focus:ring-[#171717]/6";
const financeLabelClass = "mb-2 block text-[11px] font-semibold uppercase tracking-[0.18em] text-[#2f2b28]";

function isValidPayPeriodInput(value: string) {
  const match = value.trim().match(/^(\d{4})-(\d{2})$/);

  if (!match) {
    return false;
  }

  const month = Number(match[2]);
  return month >= 1 && month <= 12;
}

function FinanceDeleteControl({ canDelete, label, onDelete }: {
  canDelete: boolean;
  label: string;
  onDelete: () => void;
}) {
  const [isConfirming, setIsConfirming] = useState(false);

  if (!canDelete) {
    return <div />;
  }

  if (!isConfirming) {
    return (
      <button
        type="button"
        onClick={() => setIsConfirming(true)}
        className="rounded-lg border border-[#d4b4a7] bg-white px-3 py-2 text-[11px] font-medium uppercase tracking-[0.16em] text-[#6a3328] transition hover:border-[#6a3328]"
      >
        {label}
      </button>
    );
  }

  return (
    <div className="flex flex-wrap items-center gap-2 rounded-lg border border-[#d4b4a7] bg-[#f8efeb] px-3 py-2">
      <span className="text-[11px] font-medium text-[#6a3328]">Delete permanently?</span>
      <button
        type="button"
        onClick={onDelete}
        className="rounded-lg bg-[#6a3328] px-3 py-1.5 text-[11px] font-medium uppercase tracking-[0.16em] text-[#f7f4f1] transition active:scale-[0.98]"
      >
        Confirm delete
      </button>
      <button
        type="button"
        onClick={() => setIsConfirming(false)}
        className="rounded-lg border border-[#d3cbc3] bg-white px-3 py-1.5 text-[11px] font-medium uppercase tracking-[0.16em] text-[#2f2b28]"
      >
        Keep
      </button>
    </div>
  );
}

