  useEffect(() => {
    if (!operatingDataLoaded || !strategicReviewsLoaded || !strategicReviewsWritableRef.current || auditRestoreInProgressRef.current) return;
    try {
      const serialized = JSON.stringify(strategicReviews);
      window.localStorage.setItem(STRATEGIC_REVIEWS_STORAGE_KEY, serialized);
      if (pendingReviewSaveRef.current) {
        if (window.localStorage.getItem(STRATEGIC_REVIEWS_STORAGE_KEY) !== serialized) throw new Error("Strategic Review write could not be verified.");
        const pending = pendingReviewSaveRef.current;
        pendingReviewSaveRef.current = null;
        if (reviewDraft?.id === pending.id && strategicReviews.some((review) => review.id === pending.id && JSON.stringify(review) === pending.snapshot)) {
          setReviewLastSavedAt(new Date().toLocaleTimeString([], { hour: "2-digit", minute: "2-digit" }));
          const currentDraftSaved = JSON.stringify(reviewDraft) === pending.snapshot;
          setReviewSaveStatus(currentDraftSaved ? "saved" : "unsaved");
          if (currentDraftSaved) setFeedback({ type: "success", message: "Strategic Review draft saved." });
        }
      }
    } catch {
      if (pendingReviewSaveRef.current) {
        pendingReviewSaveRef.current = null;
        setReviewSaveStatus("error");
      }
      setFeedback({ type: "error", message: "Strategic reviews could not be saved. Check browser storage before continuing." });
    }
  }, [strategicReviews, strategicReviewsLoaded, operatingDataLoaded]);

  const orderedCaptures = [...captures].sort(
    (first, second) =>
      new Date(second.capturedAt).getTime() - new Date(first.capturedAt).getTime(),
  );

  const orderedPeople = [...people].sort(
    (first, second) => new Date(second.dateCreated).getTime() - new Date(first.dateCreated).getTime(),
  );

  const activeLeads = leads.filter((lead) => !lead.archived);
  const archivedLeads = leads.filter((lead) => lead.archived);

  const orderedLeads = [...activeLeads].sort(
    (first, second) => new Date(second.dateCreated).getTime() - new Date(first.dateCreated).getTime(),
  );

  const orderedArchivedLeads = [...archivedLeads].sort(
    (first, second) => new Date(second.dateCreated).getTime() - new Date(first.dateCreated).getTime(),
  );

  const leadOwnerFilterOptions = Array.from(
    new Set(orderedLeads.map((lead) => lead.owner.trim() || "Unassigned")),
  ).sort();

  const orderedOutreachContacts = [...outreachContacts].sort(
    (first, second) => new Date(second.dateCreated).getTime() - new Date(first.dateCreated).getTime(),
  );
  const outreachStartOfTodayMs = new Date().setHours(0, 0, 0, 0);
  const outreachReadyForInitialOutreachContacts = orderedOutreachContacts.filter((contact) => isReadyForInitialOutreach(contact, outreachStartOfTodayMs));
  const filteredOutreachContacts = orderedOutreachContacts.filter((contact) => {
    if (outreachStatusFilter === "All statuses") return true;
    if (outreachStatusFilter === READY_FOR_INITIAL_OUTREACH_FILTER) return isReadyForInitialOutreach(contact, outreachStartOfTodayMs);
    return contact.status === outreachStatusFilter;
  });
  const outreachBucketOrder = [
    "Active prospects",
    "Replies / positive interest",
    "Future phone-only targets",
    "Closed supplier networks",
    "No response",
    "Converted to Lead",
    "Closed / Not Pursuing",
  ] as const;
  const outreachBucketCounts = outreachBucketOrder.map((bucket) => ({
    bucket,
    count: outreachContacts.filter((contact) => getOutreachBucket(contact.status) === bucket).length,
  }));

  const outreachFollowUpOrder = ["Due today", "Overdue", "Upcoming", "No follow-up scheduled"] as const;
  const outreachFollowUpCounts = outreachFollowUpOrder.map((bucket) => ({
    bucket,
    count: outreachContacts.filter((contact) => classifyOutreachFollowUp(contact, outreachStartOfTodayMs) === bucket).length,
  }));

  const filteredLeads = orderedLeads.filter((lead) => {
    const matchesStatus = leadStatusFilter === "All statuses" || lead.status === leadStatusFilter;
    const matchesSource = leadSourceFilter === "All sources" || lead.sourceChannel === leadSourceFilter;
    const matchesOwner = leadOwnerFilter === "All owners" || (lead.owner.trim() || "Unassigned") === leadOwnerFilter;
    return matchesStatus && matchesSource && matchesOwner;
  });

  const parseFinanceAmount = (value: string) => {
    const parsed = parseFloat(value.replace(/[^0-9.\-]/g, ""));
    return Number.isNaN(parsed) ? 0 : parsed;
  };
  const parseOptionalFinanceAmount = (value: string) => {
    const trimmed = value.trim();
    if (!trimmed) return null;
    const normalized = trimmed.replace(/[£$,\s]/g, "");
    if (!/^-?(?:\d+\.?\d*|\.\d+)$/.test(normalized)) return null;
    const parsed = Number(normalized);
    return Number.isFinite(parsed) ? parsed : null;
  };
  const parseCashSnapshotDate = (value: string) => {
    if (!/^\d{4}-\d{2}-\d{2}$/.test(value)) return null;
    const parsed = new Date(`${value}T00:00:00`);
    const [year, month, day] = value.split("-").map(Number);
    if (Number.isNaN(parsed.getTime()) || parsed.getFullYear() !== year || parsed.getMonth() !== month - 1 || parsed.getDate() !== day) return null;
    return parsed;
  };
  const formatFinanceAmount = (value: number) =>
    value.toLocaleString(undefined, { minimumFractionDigits: 2, maximumFractionDigits: 2 });

  const orderedIncome = [...incomeRecords].sort((a, b) => (b.date || b.dateCreated).localeCompare(a.date || a.dateCreated));
  const orderedExpenses = [...expenseRecords].sort((a, b) => (b.date || b.dateCreated).localeCompare(a.date || a.dateCreated));
  const orderedCommitments = [...commitmentRecords].sort((a, b) => (a.dueDate || a.dateCreated).localeCompare(b.dueDate || b.dateCreated));

  const orderedTaxPayments = [...taxPaymentRecords].sort((a, b) => (b.date || b.dateCreated).localeCompare(a.date || a.dateCreated));
  const taxIncomeReceived = taxPaymentRecords
    .filter((record) => record.status === "Received")
    .reduce((total, record) => total + parseFinanceAmount(record.grossAmount), 0);
  const taxIncomeOutstanding = taxPaymentRecords
    .filter((record) => record.status === "Expected")
    .reduce((total, record) => total + parseFinanceAmount(record.grossAmount), 0);
  const taxReserveRequiredOnReceived = taxIncomeReceived * TAX_RESERVE_RATE;
  const taxReserveProjectedTotal = (taxIncomeReceived + taxIncomeOutstanding) * TAX_RESERVE_RATE;
  const taxReserveAlreadySetAside = taxPaymentRecords
    .filter((record) => record.reserveSetAside)
    .reduce((total, record) => total + parseFinanceAmount(record.grossAmount) * TAX_RESERVE_RATE, 0);
  const taxReserveStillOutstanding = Math.max(0, taxReserveRequiredOnReceived - taxReserveAlreadySetAside);
  const taxPaymentsAwaitingReserve = taxPaymentRecords.filter((record) => record.status === "Received" && !record.reserveSetAside);

  const endOfMonthPayReminders = getElapsedTaxMonths(TAX_JOB_START_DATE, new Date())
    .filter(({ year, month }) => !taxPaymentRecords.some((record) => isValidPayPeriodInput(record.payPeriod) && isSameTaxMonth(record.payPeriod, year, month)))
    .map(({ year, month }) => ({
      year,
      month,
      label: new Intl.DateTimeFormat("en-GB", { month: "long", year: "numeric" }).format(new Date(year, month, 1)),
    }));

  const totalReceivedIncome = incomeRecords
    .filter((record) => record.status === "Received")
    .reduce((total, record) => total + parseFinanceAmount(record.amount), 0);
  const totalPaidExpenses = expenseRecords
    .filter((record) => record.status === "Paid")
    .reduce((total, record) => total + parseFinanceAmount(record.amount), 0);
  const netCashMovement = totalReceivedIncome - totalPaidExpenses;
  const currentCashAmount = parseOptionalFinanceAmount(cashPosition.currentCash);
  const parsedReservedTaxAmount = parseOptionalFinanceAmount(cashPosition.reservedTax);
  const parsedSafetyBufferAmount = parseOptionalFinanceAmount(cashPosition.safetyBuffer);
  const cashAmountsValid = currentCashAmount !== null && currentCashAmount >= 0
    && parsedReservedTaxAmount !== null && parsedReservedTaxAmount >= 0
    && parsedSafetyBufferAmount !== null && parsedSafetyBufferAmount >= 0;
  const reservedTaxAmount = parsedReservedTaxAmount !== null && parsedReservedTaxAmount >= 0 ? parsedReservedTaxAmount : 0;
  const safetyBufferAmount = parsedSafetyBufferAmount !== null && parsedSafetyBufferAmount >= 0 ? parsedSafetyBufferAmount : 0;
  const availableOperatingCash = cashAmountsValid ? currentCashAmount - reservedTaxAmount - safetyBufferAmount : 0;
  const cashSnapshotDateValue = normaliseCashSnapshotDate(cashPosition.lastUpdated);
  const cashSnapshotLabel = formatCashSnapshotDate(cashSnapshotDateValue);
  const cashSnapshotDate = parseCashSnapshotDate(cashSnapshotDateValue);
  const todayForCashSnapshot = new Date();
  todayForCashSnapshot.setHours(0, 0, 0, 0);
  const cashSnapshotAgeDays = cashSnapshotDate && cashSnapshotDate <= todayForCashSnapshot
    ? Math.floor((todayForCashSnapshot.getTime() - cashSnapshotDate.getTime()) / (1000 * 60 * 60 * 24))
    : null;
  const cashSnapshotFreshness: CashSnapshotFreshness = cashSnapshotAgeDays === null
    ? { label: "Missing / invalid date", tone: "warn" as const }
    : cashSnapshotAgeDays <= 7
      ? { label: "Current", tone: "clear" as const }
      : cashSnapshotAgeDays <= 30
        ? { label: "Aging", tone: "neutral" as const }
        : { label: "Stale", tone: "warn" as const };

  const getConvertedRecordsByType = (targetType: CaptureConversionRecord["targetType"]) =>
    [...conversions]
      .filter((conversion) => conversion.targetType === targetType)
      .sort(
        (first, second) => new Date(second.createdAt).getTime() - new Date(first.createdAt).getTime(),
      );

  const activeDestination = destinationDefinitions.find((destination) => destination.key === activeView);
  const problemRecords = getConvertedRecordsByType("Convert to Problem").map(normalizeProblemRecord);
  const actionRecords = getConvertedRecordsByType("Convert to Action").map(normalizeActionRecord);
  const decisionRecords = getConvertedRecordsByType("Convert to Decision").map(normalizeDecisionRecord);
  const opportunityRecords = getConvertedRecordsByType("Convert to Opportunity").map(normalizeOpportunityRecord);
  const lessonRecords = getConvertedRecordsByType("Convert to Lesson").map(normalizeLessonRecord);
  const systemRecords = getConvertedRecordsByType("Convert to System").map(normalizeSystemRecord);
  const sopRecords = getConvertedRecordsByType("Convert to SOP").map(normalizeSopRecord);

  useEffect(() => {
    if (!operatingDataLoaded || !changeHistoryLoaded || !strategicObjectivesLoaded || !strategicReviewsLoaded || !icarusLoaded) return;
    const records = (entries: object[]): Record<string, unknown>[] => entries as Record<string, unknown>[];
    const snapshot: Record<string, Record<string, unknown>[]> = {
      Capture: records(captures),
      Action: records(conversions.filter((entry) => entry.targetType === "Convert to Action")),
      Project: records(projects),
      Problem: records(conversions.filter((entry) => entry.targetType === "Convert to Problem")),
      Opportunity: records(conversions.filter((entry) => entry.targetType === "Convert to Opportunity")),
      Decision: records(conversions.filter((entry) => entry.targetType === "Convert to Decision")),
      Lesson: records(conversions.filter((entry) => entry.targetType === "Convert to Lesson")),
      System: records(conversions.filter((entry) => entry.targetType === "Convert to System")),
      SOP: records(conversions.filter((entry) => entry.targetType === "Convert to SOP")),
      Person: records(people),
      Lead: records(leads),
      Outreach: records(outreachContacts),
      "Cash position": [{ ...cashPosition, id: "cash-position" }],
      Income: records(incomeRecords),
      Expense: records(expenseRecords),
      Commitment: records(commitmentRecords),
      "Tax payment": records(taxPaymentRecords),
      "Strategic Objective": records(strategicObjectives),
      "Strategic Review": records(strategicReviews),
      "Working Relationship": records(workingRelationships),
      Icarus: records(icarusAssessments),
    };
    const previous = auditBaselineRef.current;
    if (!previous || auditRestoreInProgressRef.current) {
      auditBaselineRef.current = snapshot;
      return;
    }
    if (!changeHistoryWritableRef.current) return;
    const titles: Record<string, string> = {
      Capture: "title", Action: "actionTitle", Project: "projectName", Problem: "problemStatement",
      Opportunity: "opportunityTitle", Decision: "decisionTitle", Lesson: "lessonTitle", System: "systemName",
      SOP: "sopTitle", Person: "name", Lead: "leadName", Outreach: "businessName", "Cash position": "id",
      Income: "description", Expense: "description", Commitment: "commitmentName", "Tax payment": "description",
      "Strategic Objective": "title",
      "Strategic Review": "reviewDate",
      "Working Relationship": "id",
      Icarus: "outcome",
    };
    const events = Object.entries(snapshot).flatMap(([type, current]) =>
      diffChangeRecords(type, previous[type] || [], current, titles[type]));
    if (events.length) {
      try {
        const stored = window.localStorage.getItem(CHANGE_HISTORY_STORAGE_KEY);
        const existing: unknown = stored === null ? [] : JSON.parse(stored);
        if (!Array.isArray(existing) || !existing.every(isValidChangeEvent)) throw new Error("Stored history is invalid.");
        const next = [...existing, ...events];
        window.localStorage.setItem(CHANGE_HISTORY_STORAGE_KEY, JSON.stringify(next));
        setChangeHistory(next);
      } catch {
        setFeedback({ type: "error", message: "Change history could not be saved. Download a safety backup and check available browser storage." });
        return;
      }
    }
    auditBaselineRef.current = snapshot;
  }, [operatingDataLoaded, changeHistoryLoaded, strategicObjectivesLoaded, strategicReviewsLoaded, icarusLoaded, captures, conversions, projects, people, leads, outreachContacts, cashPosition, incomeRecords, expenseRecords, commitmentRecords, taxPaymentRecords, strategicObjectives, strategicReviews, workingRelationships, icarusAssessments]);

  const executeIntegrityAudit = (storageOverride?: Record<string, string | null>) => {
    const storage = storageOverride || Object.fromEntries(
      EMPIRE_OS_BACKUP_STORAGE_KEYS.map((key) => [key, window.localStorage.getItem(key)]),
    );
    setIntegrityAudit(runIntegrityAuditFromDomain({
      captures,
      conversions,
      actions: actionRecords,
      projects,
      problems: problemRecords,
      opportunities: opportunityRecords,
      decisions: decisionRecords,
      lessons: lessonRecords,
      systems: systemRecords,
      sops: sopRecords,
      people,
      leads,
      commitments: commitmentRecords,
      outreach: outreachContacts,
      handoffs: delegationHandoffs,
      strategicObjectives,
      strategicReviews,
      storage,
      sharedAreaOptions,
      commitmentTypeOptions,
      commitmentStatusOptions,
    }));
  };

  useEffect(() => {
    if (!operatingDataLoaded) return;
    executeIntegrityAudit(initialIntegrityStorageRef.current || undefined);
    initialIntegrityStorageRef.current = null;
  }, [operatingDataLoaded, captures, conversions, projects, people, leads, commitmentRecords, outreachContacts, delegationHandoffs, strategicObjectives, strategicReviews]);

  type AttentionItem = {
    id: string;
    objectType: "Problem" | "Action" | "Decision" | "Opportunity" | "Project" | "Lead" | "Lesson" | "System" | "SOP" | "Outreach" | "Finance" | "Icarus";
    title: string;
    reason: string;
    reasons: string[];
    statusText: string;
    area: string;
    attentionRank: number;
    tieWeight: number;
    priorityScore: number;
    sortDate: number;
    sortDateAscending: boolean;
    targetCompletionDate?: string;
    onOpen: () => void;
    dependencyAction?: {
      label: string;
      onOpen: () => void;
    };
    strategicRisk?: {
      summary: string;
      references: IcarusAttentionReference[];
    };
    operationalPriorityScore?: number;
    convergentStrategicRisk?: {
      clusterKey: string;
      rootRecordKey: string;
      riskRecordKeys: string[];
    };
    strategicRiskAction?: {
      label: string;
      onOpen: () => void;
    };
  };

  const getAreaText = (record: { relatedArea?: string; relatedPillar?: string; area?: string; }) => {
    return record.relatedPillar || record.relatedArea || record.area || "";
  };

  const getDateValue = (value?: string) => {
    if (!value) {
      return 0;
    }

    const parsed = new Date(value);
    return Number.isNaN(parsed.getTime()) ? 0 : parsed.getTime();
  };

  const isActionActive = (action: ActionRecord) =>
    ["Open", "In Progress", "Blocked"].includes(action.status) || isActionWaiting(action);

  const isReleaseInterventionAction = (action: ActionRecord) =>
    Boolean(action.releaseSourceType && action.releaseSourceId && action.releaseIntent);

  const isProblemUnresolved = (problem: ProblemRecord) =>
    ["Open", "Investigating", "Action required"].includes(problem.problemStatus);

  const isDecisionActive = (decision: DecisionRecord) =>
    ["Draft", "Active", "Under Review"].includes(decision.decisionStatus);

  const isDecisionReviewDue = (decision: DecisionRecord) => {
    if (!isDecisionActive(decision) || !decision.reviewDate) return false;
    const reviewTime = new Date(decision.reviewDate).getTime();
    return !Number.isNaN(reviewTime) && reviewTime <= Date.now();
  };

  const isOpportunityUnderEvaluation = (opportunity: OpportunityRecord) =>
    opportunity.status === "Evaluating" && ["High", "Exceptional"].includes(opportunity.strategicFit);

  const isProjectActive = (project: ProjectRecord) =>
    !["completed", "closed", "final", "cancelled", "canceled"].includes(project.status.trim().toLowerCase());

  const delegationReadiness = assessDelegationReadiness(orderedPeople);
  const {
    primaryFounder: founderPerson,
    activeOperationalPeople: activeOperationalDelegationPeople,
    readyPeople: delegationReadyPeople,
    readinessGapPeople: delegationReadinessGapPeople,
    teamReadinessGapPeople: teamDelegationReadinessGapPeople,
    cofounderReadinessGapPeople,
  } = delegationReadiness;
  const getDelegationReadyPeopleForArea = (area: string) =>
    getDelegationReadyPeopleForAreaRule(area, delegationReadyPeople);

  const founderOwnerKey = founderPerson?.name.trim().toLowerCase() || null;
  const getValidActiveOwnerKey = (ownerText: string | undefined, ownerPersonId?: string) =>
    resolveActiveOwnerKey(orderedPeople, ownerText, ownerPersonId);
  const isFounderOwned = (ownerText: string | undefined, ownerPersonId?: string) =>
    isFounderOwnedRule(founderPerson, orderedPeople, { owner: ownerText, ownerPersonId });
  const activeOwnershipActions = actionRecords.filter((action) => isActionActive(action) && !isReleaseInterventionAction(action));
  const activeOwnershipProjects = projects.filter(isProjectActive);
  const activeOwnershipLeads = activeLeads.filter((lead) => !["Won", "Lost"].includes(lead.status));
  const activeOwnershipProblems = problemRecords.filter(isProblemUnresolved);

  const {
    metricsLeadsGenerated,
    metricsLeadsBySource,
    metricsJobsWon,
    metricsQuotesSent,
    metricsLeadToJobConversion,
    metricsRevenueFromWonLeads,
    metricsAverageJobValue,
    acquisitionChannelPerformance,
    acquisitionSourceDetailPerformance,
  } = buildAcquisitionAnalytics(activeLeads, parseFinanceAmount);

  const wonLeadsValue = (lead: LeadRecord) =>
    getWonLeadValue(lead, parseFinanceAmount);

  const metricsOpenActions = actionRecords.filter((action) => action.status === "Open").length;
  const metricsInProgressActions = actionRecords.filter((action) => action.status === "In Progress").length;
  const metricsCompletedActions = actionRecords.filter((action) => action.status === "Completed").length;
  const metricsActiveProjects = projects.filter((project) => isProjectActive(project)).length;
  const metricsBlockedProjects = projects.filter((project) => project.status.trim().toLowerCase() === "blocked").length;

  const pillarOptions = ["Garden Maintenance", "Hard Landscape Construction", "Excavation"] as const;
  const icarusSourceRecords: IcarusSourceRecord[] = [
    ...captures.map((record) => ({ recordType: "Capture" as const, recordId: record.id, title: record.title })),
    ...problemRecords.map((record) => ({ recordType: "Problem" as const, recordId: record.id, title: record.problemStatement || record.title })),
    ...actionRecords.map((record) => ({ recordType: "Action" as const, recordId: record.id, title: record.actionTitle || record.title })),
    ...decisionRecords.map((record) => ({ recordType: "Decision" as const, recordId: record.id, title: record.decisionTitle || record.title })),
    ...lessonRecords.map((record) => ({ recordType: "Lesson" as const, recordId: record.id, title: record.lessonTitle || record.title })),
    ...projects.map((record) => ({
      recordType: "Project" as const,
      recordId: record.id,
      title: record.projectName,
      status: record.status,
      health: record.health,
      relevantAt: record.lastReviewedDate,
    })),
    ...systemRecords.map((record) => ({
      recordType: "System" as const,
      recordId: record.id,
      title: record.systemName || record.title,
      status: record.status,
    })),
    ...sopRecords.map((record) => ({
      recordType: "SOP" as const,
      recordId: record.id,
      title: record.sopTitle || record.title,
      status: record.status,
    })),
    ...opportunityRecords.map((record) => ({ recordType: "Opportunity" as const, recordId: record.id, title: record.opportunityTitle || record.title })),
    ...leads.map((record) => ({ recordType: "Lead" as const, recordId: record.id, title: record.leadName })),
    ...outreachContacts.map((record) => ({ recordType: "Outreach" as const, recordId: record.id, title: record.businessName })),
    ...commitmentRecords.map((record) => ({ recordType: "Commitment" as const, recordId: record.id, title: record.commitmentName })),
    { recordType: "Finance", recordId: "cash-position", title: "Cash position" },
    ...people.map((record) => ({
      recordType: "Person" as const,
      recordId: record.id,
      title: record.name,
      status: record.status,
    })),
    ...pillarOptions.map((pillar) => ({ recordType: "Pillar" as const, recordId: pillar, title: pillar })),
    ...strategicObjectives.map((record) => ({ recordType: "Strategic Objective" as const, recordId: record.id, title: record.title })),
  ];
  const pillarSummaries = pillarOptions.map((pillar) => {
    const pillarProjects = projects.filter((project) => project.area === pillar && isProjectActive(project));
    const pillarActions = actionRecords.filter((action) => action.relatedPillar === pillar && isActionActive(action));
    const pillarProblems = problemRecords.filter((problem) => getAreaText(problem) === pillar && isProblemUnresolved(problem));
    const pillarOpportunities = opportunityRecords.filter((opportunity) => (opportunity.relatedPillar || opportunity.relatedArea || "") === pillar && ["New", "Evaluating", "On Hold"].includes(opportunity.status));
    const pillarLeads = activeLeads.filter((lead) => (lead.relatedPillar || "") === pillar);
    const pillarFollowUpLeads = pillarLeads.filter((lead) => lead.status === "Follow-Up");
    const pillarWonLeadsValue = pillarLeads
      .filter((lead) => lead.status === "Won")
      .reduce((total, lead) => total + wonLeadsValue(lead), 0);

    const priorityScore = (
      pillarProblems.length * 6 +
      pillarActions.filter((action) => action.status === "Blocked").length * 8 +
      pillarActions.filter((action) => !isActionWaiting(action) && action.dueDate && new Date(action.dueDate).getTime() <= Date.now()).length * 3 +
      pillarProjects.filter((project) => project.status.trim().toLowerCase() === "blocked").length * 5 +
      pillarFollowUpLeads.length * 2 +
      pillarOpportunities.length * 2
    );

    return {
      pillar,
      activeProjects: pillarProjects.length,
      blockedProjects: pillarProjects.filter((project) => project.status.trim().toLowerCase() === "blocked").length,
      openActions: pillarActions.length,
      openProblems: pillarProblems.length,
      openOpportunities: pillarOpportunities.length,
      leadsWaiting: pillarFollowUpLeads.length,
      wonLeadValue: pillarWonLeadsValue,
      priorityScore,
    };
  });

  const empireDecisionQueue: EmpireDecisionQueueResult = buildEmpireDecisionQueue({
    decisions: decisionRecords,
    problems: problemRecords,
    actions: actionRecords,
    projects,
    opportunities: opportunityRecords,
    leads: activeLeads,
    activeOwnershipActions,
    activeOwnershipProjects,
    activeOwnershipLeads,
    activeOwnershipProblems,
    systems: systemRecords,
    orderedPeople: orderedPeople.map(({ id, name, role, accessLevel, status, responsibilities, authority, pillar }) => ({
      id,
      name,
      role,
      accessLevel,
      status,
      responsibilities,
      authority,
      pillar,
    })),
    nowMs: Date.now(),
  });

  const toOperationalIndependenceWorkItem = (
    item: {
      id: string;
      objectType: "Action" | "Project" | "Lead" | "Problem";
      title: string;
      owner: string;
      ownerPersonId?: string;
      pillar: string;
      hasImmediateFounderIntervention: boolean;
    },
  ) => {
    const ownerKey = getValidActiveOwnerKey(item.owner, item.ownerPersonId);
    const ownerPerson = ownerKey
      ? orderedPeople.find((person) => person.status === "Active" && person.name.trim().toLowerCase() === ownerKey) || null
      : null;
    const founderOwned = isFounderOwned(item.owner, item.ownerPersonId);

    return {
      id: item.id,
      objectType: item.objectType,
      title: item.title,
      owner: item.owner,
      ...(item.objectType === "Action" ? { ownerPersonId: item.ownerPersonId } : {}),
      pillar: item.pillar,
      hasImmediateFounderIntervention: item.hasImmediateFounderIntervention,
      hasValidActiveOwner: ownerPerson !== null,
      isFounderOwned: founderOwned,
      areaHasDelegationReadyPerson: ownerPerson && founderOwned
        ? getDelegationReadyPeopleForArea(item.pillar).length > 0
        : false,
      ownerReadinessMissingFields: ownerPerson && !founderOwned
        ? getDelegationReadinessMissingFields(ownerPerson)
        : [],
    };
  };
  const operationalIndependence = buildOperationalIndependence({
    actions: activeOwnershipActions.map((action) => toOperationalIndependenceWorkItem({
      id: action.id,
      objectType: "Action",
      title: action.actionTitle,
      owner: getActionOwnerDisplay(action, people),
      ownerPersonId: action.ownerPersonId,
      pillar: action.relatedPillar || "Unassigned",
      hasImmediateFounderIntervention: action.status === "Blocked",
    })),
    projects: activeOwnershipProjects.map((project) => toOperationalIndependenceWorkItem({
      id: project.id,
      objectType: "Project",
      title: project.projectName,
      owner: project.owner || "Unassigned",
      pillar: project.area || "Unassigned",
      hasImmediateFounderIntervention: false,
    })),
    leads: activeOwnershipLeads.map((lead) => toOperationalIndependenceWorkItem({
      id: lead.id,
      objectType: "Lead",
      title: lead.leadName,
      owner: lead.owner || "Unassigned",
      pillar: lead.relatedPillar || "Unassigned",
      hasImmediateFounderIntervention: false,
    })),
    problems: activeOwnershipProblems.map((problem) => toOperationalIndependenceWorkItem({
      id: problem.id,
      objectType: "Problem",
      title: problem.problemStatement,
      owner: problem.owner || "Unassigned",
      pillar: getAreaText(problem) || "Unassigned",
      hasImmediateFounderIntervention: problem.problemStatus === "Action required",
    })),
    founderReviewItems: empireDecisionQueue.founderReviewQueue.map(({ kind, id }) => ({ kind, id })),
    founderAuthorityItems: empireDecisionQueue.founderAuthorityItems.map(({ objectType, id }) => ({ objectType, id })),
    delegationReadyPeopleCount: delegationReadyPeople.length,
    delegationReadinessGapPeopleCount: delegationReadinessGapPeople.length,
  });
  const founderDependentWork = operationalIndependence.classifiedItems
    .filter((item) => item.state === "Founder-only")
    .map(({ objectType, id }) => ({ objectType, id }));
  // Icarus Stage A (see icarus-intelligence-pipeline): after People/operational independence so ownership can be
  // judged against founder dependency, and before Command Attention, which ranks the resulting strategic signals.
  const icarusTreatmentActions = actionRecords.map((action) => ({
    recordType: "Action" as const,
    recordId: action.id,
    title: action.actionTitle || action.title,
    status: action.status,
    owner: action.owner,
    ownerPersonId: action.ownerPersonId,
    dueDate: action.dueDate,
    priority: action.priority,
    context: getAreaText(action),
  }));
  const icarusTreatmentProjects = projects.map((project) => ({
    recordType: "Project" as const,
    recordId: project.id,
    title: project.projectName,
    status: project.status,
    owner: project.owner,
    dueDate: project.targetCompletionDate,
    blocked: project.health === "Blocked" || project.status === "Blocked",
    context: project.area,
  }));
  const icarusIntelligence = buildIcarusStrategicIntelligence({
    assessments: icarusAssessments,
    sourceRecords: icarusSourceRecords,
    strategicObjectives,
    people: people.map(({ id, status }) => ({ id, status })),
    actions: actionRecords.map(({ id, status, dueDate }) => ({ id, status, dueDate })),
    treatmentActions: icarusTreatmentActions,
    treatmentProjects: icarusTreatmentProjects,
    primaryFounderId: founderPerson?.id ?? null,
    founderDependencyActive: founderDependentWork.length > 0,
  });
  const icarusTreatmentIndex = icarusIntelligence.treatment;
  const icarusResolutionReviewItems = icarusAssessments.flatMap((assessment) =>
    icarusIntelligence.lifecycle.byAssessmentId.get(assessment.id)?.eligibility.state === "Eligible for human review"
      ? [{ assessmentId: assessment.id, title: assessment.outcome }]
      : []);
  const icarusInterventionIndex = buildIcarusInterventionIndex({
    assessments: icarusAssessments,
    treatment: icarusTreatmentIndex,
    signals: icarusIntelligence.strategicSignals,
    sources: icarusSourceRecords,
    decisions: decisionRecords,
    lessons: lessonRecords,
    people,
    nowMs: icarusIntelligence.nowMs,
    lifecycle: icarusIntelligence.lifecycle,
  });
  const icarusSignalsWithTreatment = icarusIntelligence.strategicSignals.map((signal) => {
    const treatment = icarusTreatmentIndex.summaries.get(signal.assessmentId);
    return treatment ? {
      ...signal,
      treatment: {
        attentionReasons: [
          ...treatment.attentionReasons,
          ...(icarusInterventionIndex.attentionByAssessmentId.get(signal.assessmentId) ?? []),
        ],
        founderOwnedCount: treatment.founderOwnedCount,
        delegatedCount: treatment.delegatedCount,
      },
    } : signal;
  });
  const icarusStressTestingInput = {
    assessments: icarusAssessments,
    sourceRecords: icarusSourceRecords,
    strategicObjectives,
    people: people.map(({ id, status }) => ({ id, status })),
    actions: actionRecords.map(({ id, status, dueDate }) => ({ id, status, dueDate })),
    primaryFounderId: founderPerson?.id ?? null,
    founderDependencyActive: founderDependentWork.length > 0,
    founderDependentWork,
    operationalIndependenceWork: operationalIndependence.classifiedItems.map(({ objectType, id, title, pillar, state }) => ({
      objectType,
      id,
      title,
      pillar,
      state,
    })),
    nowMs: icarusIntelligence.nowMs,
  };

  const decisionTrackRecord = (() => {
    const validOutcomeRatings = new Set(["Worked", "Partially worked", "Failed"]);
    const isClosed = (decision: DecisionRecord) => ["Completed", "Reversed"].includes(decision.decisionStatus);
    const hasValidRating = (decision: DecisionRecord) => validOutcomeRatings.has(decision.outcomeRating);
    const reviewedDecisions = decisionRecords.filter((decision) => isClosed(decision) && hasValidRating(decision));
    const closedButUnrated = decisionRecords.filter((decision) => isClosed(decision) && !hasValidRating(decision));
    const ratedWhileActive = decisionRecords.filter((decision) => !isClosed(decision) && hasValidRating(decision));
    const reviewsDue = decisionRecords.filter(isDecisionReviewDue);
    const ratings = { worked: 0, partially: 0, failed: 0 };
    reviewedDecisions.forEach((decision) => {
      if (decision.outcomeRating === "Worked") ratings.worked += 1;
      else if (decision.outcomeRating === "Partially worked") ratings.partially += 1;
      else ratings.failed += 1;
    });
    const byMaker = new Map<string, { maker: string; total: number; worked: number; partially: number; failed: number }>();
    reviewedDecisions.forEach((decision) => {
      const storedMaker = decision.decisionMaker.trim() || "Unassigned";
      const makerKey = storedMaker.toLowerCase();
      const matchedPerson = orderedPeople.find((person) => person.name.trim().toLowerCase() === makerKey);
      const maker = matchedPerson?.name.trim() || storedMaker;
      const entry = byMaker.get(makerKey) || { maker, total: 0, worked: 0, partially: 0, failed: 0 };
      entry.total += 1;
      if (decision.outcomeRating === "Worked") entry.worked += 1;
      if (decision.outcomeRating === "Partially worked") entry.partially += 1;
      if (decision.outcomeRating === "Failed") entry.failed += 1;
      byMaker.set(makerKey, entry);
    });
    const byArea = new Map<string, { total: number; worked: number; partially: number; failed: number }>();
    reviewedDecisions.forEach((decision) => {
      const area = getAreaText(decision) || "Unassigned";
      const entry = byArea.get(area) || { total: 0, worked: 0, partially: 0, failed: 0 };
      entry.total += 1;
      if (decision.outcomeRating === "Worked") entry.worked += 1;
      if (decision.outcomeRating === "Partially worked") entry.partially += 1;
      if (decision.outcomeRating === "Failed") entry.failed += 1;
      byArea.set(area, entry);
    });
    const decisionsWithMeaningfulLessons = reviewedDecisions.filter((decision) =>
      lessonRecords.some((lesson) => lesson.relatedDecision === decision.id && ["Reviewed", "Implemented"].includes(lesson.status)),
    ).length;
    const actualOutcomeRecorded = reviewedDecisions.filter((decision) => decision.actualOutcome.trim() !== "").length;
    return {
      reviewsDue,
      reviewedDecisions,
      closedButUnrated,
      ratedWhileActive,
      ratings,
      byMaker: [...byMaker.values()],
      byArea: [...byArea.entries()].map(([area, counts]) => ({ area, ...counts })),
      decisionsWithMeaningfulLessons,
      actualOutcomeRecorded,
    };
  })();

  const recurringProblemLearning = buildRecurringProblemLearning({
    problems: problemRecords.map((problem) => ({
      id: problem.id,
      frequency: problem.frequency,
      severity: problem.severity,
      problemStatus: problem.problemStatus,
      problemStatement: problem.problemStatement,
      title: problem.title,
      owner: problem.owner,
      relatedPillar: problem.relatedPillar,
      relatedArea: problem.relatedArea,
      area: problem.area,
      isUnresolved: isProblemUnresolved(problem),
    })),
    lessons: lessonRecords.map(({ id, relatedProblem, relatedSystem, status }) => ({ id, relatedProblem, relatedSystem, status })),
    systems: systemRecords.map(({ id, relatedLesson, status }) => ({ id, relatedLesson, status })),
    sops: sopRecords.map(({ relatedLesson, relatedSystem, status }) => ({ relatedLesson, relatedSystem, status })),
  });

  const decisionExecutionRecords = decisionRecords
    .filter((decision) => ["Active", "Under Review"].includes(decision.decisionStatus))
    .map((decision) => ({
      id: decision.id,
      objectType: "Decision" as const,
      title: decision.decisionTitle || decision.title,
      status: decision.decisionStatus,
      area: getAreaText(decision) || "Unassigned",
      owner: decision.decisionMaker || "Unassigned",
      execution: deriveDecisionExecutionState(decision, actionRecords, projects),
    }));
  const decisionsWithoutExecution = decisionExecutionRecords
    .filter((decision) => decision.execution.state === "No execution path")
    .map((decision) => ({ ...decision, reason: "No direct or project-mediated implementation work" }));
  const decisionsWithActiveExecution = decisionExecutionRecords
    .filter((decision) => decision.execution.state === "Active execution");
  const decisionsWithBlockedExecution = decisionExecutionRecords
    .filter((decision) => decision.execution.state === "Blocked execution")
    .map((decision) => ({ ...decision, reason: "Every current implementation route is blocked" }));
  const decisionsWithCompletedExecution = decisionExecutionRecords
    .filter((decision) => decision.execution.state === "Completed execution")
    .map((decision) => ({ ...decision, reason: "Implementation complete — decision may need closure or review" }));

  const selectedPillarDetail = selectedPillar ? (() => {
    const blockedProjects = projects.filter((project) => project.area === selectedPillar && project.status.trim().toLowerCase() === "blocked");
    const overdueActions = actionRecords.filter((action) => action.relatedPillar === selectedPillar &&
      !isActionWaiting(action) &&
      action.status !== "Completed" &&
      action.status !== "Cancelled" &&
      action.dueDate &&
      new Date(action.dueDate).getTime() <= Date.now());
    const unresolvedProblems = problemRecords.filter((problem) => getAreaText(problem) === selectedPillar && isProblemUnresolved(problem));
    const openOpportunities = opportunityRecords.filter((opportunity) =>
      (opportunity.relatedPillar || opportunity.relatedArea || "") === selectedPillar &&
      ["New", "Evaluating", "On Hold"].includes(opportunity.status),
    );
    const followUpLeads = activeLeads.filter((lead) => (lead.relatedPillar || "") === selectedPillar && lead.status === "Follow-Up");

    const sections: Array<{
      label: string;
      items: Array<{
        id: string;
        objectType: string;
        title: string;
        meta: string;
        why: string;
      }>;
    }> = [
      {
        label: "Blocked projects",
        items: blockedProjects.map((project) => ({
          id: project.id,
          objectType: "Project",
          title: project.projectName,
          meta: `${project.owner} • ${project.status}`,
          why: project.targetCompletionDate
            ? `This project is blocked and has a target completion of ${project.targetCompletionDate}. That keeps delivery and revenue timing uncertain for this pillar.`
            : "This project is blocked, which means work is stalled and the pillar is carrying execution risk until it is resolved.",
        })),
      },
      {
        label: "Overdue actions",
        items: overdueActions.map((action) => ({
          id: action.id,
          objectType: "Action",
          title: action.actionTitle,
          meta: `${action.owner || "Unassigned"} • ${action.status} • ${action.priority}`,
          why: action.dueDate
            ? `The due date was ${action.dueDate}. This action is overdue and is now creating execution drag for the current workstream.`
            : "This action is still active but has no clear deadline, so it is at risk of slipping and delaying dependent work.",
        })),
      },
      {
        label: "Unresolved problems",
        items: unresolvedProblems.map((problem) => ({
          id: problem.id,
          objectType: "Problem",
          title: problem.problemStatement,
          meta: `${problem.severity} • ${problem.problemStatus} • ${problem.owner || "Unassigned"}`,
          why: problem.severity === "Critical" || problem.severity === "High"
            ? `This problem is ${problem.severity.toLowerCase()} and still ${problem.problemStatus.toLowerCase()}. It is materially affecting quality, safety, or delivery reliability.`
            : `This problem is still ${problem.problemStatus.toLowerCase()} and remains unresolved, so it is likely reducing productivity or increasing rework in this pillar.`,
        })),
      },
      {
        label: "Open opportunities",
        items: openOpportunities.map((opportunity) => ({
          id: opportunity.id,
          objectType: "Opportunity",
          title: opportunity.opportunityTitle,
          meta: `${opportunity.status} • ${opportunity.strategicFit} fit • ${opportunity.owner || "Unassigned"}`,
          why: opportunity.status === "Evaluating" || opportunity.status === "On Hold"
            ? `This opportunity is still ${opportunity.status.toLowerCase()} and is not yet converted into revenue. It is a live growth lever that needs a decision or follow-through.`
            : `This opportunity is still active, and the current status means it needs attention before it slips or is lost to competitors.`,
        })),
      },
      {
        label: "Leads needing follow-up",
        items: followUpLeads.map((lead) => ({
          id: lead.id,
          objectType: "Lead",
          title: lead.leadName,
          meta: `${lead.serviceRequested} • ${lead.owner || "Unassigned"} • ${lead.followUpDate || "Follow-up date not set"}`,
          why: lead.followUpDate
            ? `The follow-up date was ${lead.followUpDate}. This lead is waiting for a response, so momentum is at risk of stalling into lost opportunity.`
            : "This lead is marked for follow-up and is still waiting for a response, which means the deal is not yet moving forward.",
        })),
      },
    ];

    return {
      pillar: selectedPillar,
      sections,
    };
  })() : null;

  const toAccountabilityRiskInput = (record: AccountabilityRiskInput): AccountabilityRiskInput => ({
    dueDate: record.dueDate,
    targetCompletionDate: record.targetCompletionDate,
    createdAt: record.createdAt,
    priority: record.priority,
    severity: record.severity,
  });
  const accountabilityPolicyInput = {
    orderedPeople: orderedPeople.map(({ id, name, status }) => ({ id, name, status })),
    actions: actionRecords.map((action) => ({
      ...toAccountabilityRiskInput(action),
      owner: action.owner,
      ownerPersonId: action.ownerPersonId,
      status: action.status,
      isActive: isActionActive(action),
      isWaiting: isActionWaiting(action),
    })),
    projects: projects.map((project) => ({
      ...toAccountabilityRiskInput(project),
      owner: project.owner,
      status: project.status,
      isActive: isProjectActive(project),
    })),
    activeLeads: activeLeads.map(({ owner, status, followUpDate }) => ({ owner, status, followUpDate })),
    decisions: decisionRecords.map(({ decisionMaker, decisionStatus, reviewDate }) => ({
      decisionMaker, decisionStatus, reviewDate,
    })),
    problems: problemRecords.map((problem) => ({
      ...toAccountabilityRiskInput(problem),
      owner: problem.owner,
      isUnresolved: isProblemUnresolved(problem),
    })),
  };
  const buildAccountabilitySnapshot = (person: PersonRecord | null) => {
    const snapshot = buildAccountabilitySnapshotPolicy({
      ...accountabilityPolicyInput,
      person: person ? { id: person.id, name: person.name } : null,
      nowMs: Date.now(),
    });
    return {
      person,
      ownerLabel: snapshot.ownerLabel,
      ownedActions: snapshot.ownedActions.map((index) => actionRecords[index]),
      overdueActions: snapshot.overdueActions.map((index) => actionRecords[index]),
      blockedActions: snapshot.blockedActions.map((index) => actionRecords[index]),
      otherOpenActions: snapshot.otherOpenActions.map((index) => actionRecords[index]),
      activeProjects: snapshot.activeProjects.map((index) => projects[index]),
      blockedProjects: snapshot.blockedProjects.map((index) => projects[index]),
      otherActiveProjects: snapshot.otherActiveProjects.map((index) => projects[index]),
      pipelineLeads: snapshot.pipelineLeads.map((index) => activeLeads[index]),
      followUpLeads: snapshot.followUpLeads.map((index) => activeLeads[index]),
      otherPipelineLeads: snapshot.otherPipelineLeads.map((index) => activeLeads[index]),
      waitingDecisions: snapshot.waitingDecisions.map((index) => decisionRecords[index]),
      unresolvedProblems: snapshot.unresolvedProblems.map((index) => problemRecords[index]),
      blockedCount: snapshot.blockedCount,
      carriedCount: snapshot.carriedCount,
      attentionCount: snapshot.attentionCount,
    };
  };

  const personAccountabilitySummaries = orderedPeople.map((person) => ({ ...buildAccountabilitySnapshot(person), person }));
  const unassignedAccountability = buildAccountabilitySnapshot(null);
  const handoffSourceFacts: HandoffSourceInput[] = [
    ...actionRecords.map((action) => ({
      objectType: "Action" as const,
      id: action.id,
      owner: action.owner,
      ownerPersonId: action.ownerPersonId,
      status: action.status,
      dueDate: action.dueDate,
    })),
    ...projects.map((project) => ({
      objectType: "Project" as const,
      id: project.id,
      owner: project.owner,
      status: project.status,
      targetCompletionDate: project.targetCompletionDate,
    })),
    ...leads.map((lead) => ({
      objectType: "Lead" as const,
      id: lead.id,
      owner: lead.owner,
      status: lead.status,
      followUpDate: lead.followUpDate,
    })),
    ...problemRecords.map((problem) => ({
      objectType: "Problem" as const,
      id: problem.id,
      owner: problem.owner,
      problemStatus: problem.problemStatus,
      severity: problem.severity,
    })),
  ];
  const delegationHandoffFollowThrough = deriveDelegationHandoffFollowThrough(
    delegationHandoffs,
    handoffSourceFacts,
    people,
    founderPerson,
    Date.now(),
    orderedPeople,
  );
  const delegationHandoffFactsByPerson = delegationHandoffFollowThrough.items.reduce((factsByPerson, handoff) => {
    const facts = factsByPerson.get(handoff.newOwnerPersonId) || {
      received: 0,
      healthy: 0,
      atRisk: 0,
      completed: 0,
      cancelled: 0,
      returnedToFounder: 0,
      ownershipChanged: 0,
      sourceMissing: 0,
      reviewDue: 0,
      interventionRequired: 0,
    };
    facts.received += 1;
    if (handoff.state === "Healthy") facts.healthy += 1;
    if (handoff.state === "At risk") facts.atRisk += 1;
    if (handoff.state === "Completed") facts.completed += 1;
    if (handoff.state === "Cancelled") facts.cancelled += 1;
    if (handoff.state === "Returned to Founder") facts.returnedToFounder += 1;
    if (handoff.state === "Ownership changed") facts.ownershipChanged += 1;
    if (handoff.state === "Source missing") facts.sourceMissing += 1;
    if (handoff.reviewState === "Review due") facts.reviewDue += 1;
    if (handoff.reviewState === "Intervention required") facts.interventionRequired += 1;
    factsByPerson.set(handoff.newOwnerPersonId, facts);
    return factsByPerson;
  }, new Map<string, {
    received: number;
    healthy: number;
    atRisk: number;
    completed: number;
    cancelled: number;
    returnedToFounder: number;
    ownershipChanged: number;
    sourceMissing: number;
    reviewDue: number;
    interventionRequired: number;
  }>());
  const getCapacityRankedDelegationPeopleForArea = (area: string): CapacityRankedDelegationPerson[] => {
    const capacityFacts = personAccountabilitySummaries.map((entry) => ({
      personId: entry.person.id,
      carriedCount: entry.carriedCount,
      attentionCount: entry.attentionCount,
    }));
    return rankDelegationPeopleForArea(area, delegationReadyPeople, capacityFacts).flatMap((rankedPerson) => {
      const person = delegationReadyPeople.find((entry) => entry.id === rankedPerson.id);
      return person
        ? [{ ...person, carriedCount: rankedPerson.carriedCount, attentionCount: rankedPerson.attentionCount }]
        : [];
    });
  };

  const organisationalHealthWorkItems = [
    ...activeOwnershipActions.map((action) => ({ ownerKey: getValidActiveOwnerKey(action.owner, action.ownerPersonId) })),
    ...projects
      .filter((project) => ["open", "in progress", "blocked"].includes(project.status.trim().toLowerCase()))
      .map((project) => ({ ownerKey: getValidActiveOwnerKey(project.owner) })),
    ...activeOwnershipLeads.map((lead) => ({ ownerKey: getValidActiveOwnerKey(lead.owner) })),
    ...activeOwnershipProblems.map((problem) => ({ ownerKey: getValidActiveOwnerKey(problem.owner) })),
  ];
  const organisationalHealthNowMs = Date.now();
  const organisationalHealth = buildOrganisationalHealth({
    workItems: organisationalHealthWorkItems,
    founderOwnerKey,
    healthyHandoffCount: delegationHandoffFollowThrough.healthy,
    atRiskHandoffCount: delegationHandoffFollowThrough.atRisk,
    decisions: decisionRecords.map((decision) => ({
      status: decision.decisionStatus,
      startDate: decision.decisionDate || decision.createdAt,
    })),
    nowMs: organisationalHealthNowMs,
  });

  const capitalAllocation = buildCapitalAllocation({
    opportunities: opportunityRecords.filter((opportunity) => ["New", "Evaluating", "On Hold", "Approved"].includes(opportunity.status)).map((opportunity) => ({
      opportunity,
      upside: parseFinanceAmount(opportunity.estimatedUpside),
      parsedCapital: parseOptionalFinanceAmount(opportunity.requiredCapital.trim()),
    })),
    commitments: commitmentRecords.map((commitment) => ({
      commitment,
      amount: parseOptionalFinanceAmount(commitment.amount),
      originalBudget: parseOptionalFinanceAmount(commitment.originalBudget || ""),
      targetPrice: parseOptionalFinanceAmount(commitment.targetPrice || ""),
      actualPurchasePrice: parseOptionalFinanceAmount(commitment.actualPurchasePrice || ""),
      dueDateValid: Boolean(parseCashSnapshotDate(commitment.dueDate)),
      quoteState: getProcurementQuoteState(commitment),
    })),
    leads: leads.filter((lead) => lead.status === "Won").map((lead) => ({
      lead,
      finalValue: parseOptionalFinanceAmount(lead.finalJobValue),
      quoteValue: parseOptionalFinanceAmount(lead.quoteValue),
    })),
    currentCashAmount,
    cashAmountsValid,
    reservedTaxAmount,
    safetyBufferAmount,
    cashSnapshotFreshness,
    cashSnapshotAgeDays,
    nowMs: Date.now(),
  });

  const strategicDataConfidence = buildStrategicDataConfidence({
    cashConfigured: capitalAllocation.cashConfigured,
    cashSnapshotFreshnessLabel: capitalAllocation.cashSnapshotFreshness.label,
    commitmentsNeedingAttention: capitalAllocation.commitmentsNeedingAttention.map(({ commitment }) => ({ id: commitment.id })),
    highFitMissingCapitalCount: capitalAllocation.highFitMissingCapitalCount,
    highFitQualitativeCapitalCount: capitalAllocation.highFitQualitativeCapitalCount,
    liveOpportunities: capitalAllocation.liveOpportunities.map(({ id, fitRank, capitalState }) => ({ id, fitRank, capitalState })),
    totalWork: organisationalHealth.totalWork,
    validOwned: organisationalHealth.validOwned,
    closedButUnrated: decisionTrackRecord.closedButUnrated.map(({ id }) => ({ id })),
    totalWonLeads: capitalAllocation.wonCommercialEvidence.totalWonLeads,
    totalMissingFinalValues: capitalAllocation.wonCommercialEvidence.totalMissingFinalValues,
    wonLeads: leads
      .filter((lead) => lead.status === "Won")
      .map((lead) => ({ id: lead.id, parsedFinalValue: parseOptionalFinanceAmount(lead.finalJobValue) })),
  });

  const isBlankOwnerText = (ownerValue?: string) => {
    const text = (ownerValue || "").trim();
    return text === "" || text.toLowerCase() === "unassigned";
  };
  const ownershipGapLabel = (ownerValue?: string) => (isBlankOwnerText(ownerValue) ? "Unassigned" : "Invalid / inactive owner");

  const staleUnownedWork = (() => {
    const now = Date.now();
    const staleThresholdMs = 1000 * 60 * 60 * 24 * 7;
    const ageMs = (dateText?: string) => {
      if (!dateText) return 0;
      const parsed = new Date(dateText).getTime();
      return Number.isNaN(parsed) ? 0 : now - parsed;
    };
    const isStale = (dateText?: string) => {
      const ms = ageMs(dateText);
      return ms > staleThresholdMs;
    };
    const movementDate = (record: { dueDate?: string; createdAt?: string; targetCompletionDate?: string }) =>
      record.dueDate || record.targetCompletionDate || record.createdAt;

    const items: Array<{
      key: string;
      objectType: string;
      id: string;
      title: string;
      area: string;
      owner: string;
      gapLabel: string;
      staleDays: number;
      score: number;
    }> = [];

    unassignedAccountability.ownedActions.forEach((action) => {
      const moved = movementDate(action);
      if (!isStale(moved)) return;
      items.push({
        key: `Action:${action.id}`,
        objectType: "Action",
        id: action.id,
        title: action.actionTitle,
        area: action.relatedPillar || "Unassigned",
        owner: action.owner || "Unassigned",
        gapLabel: ownershipGapLabel(action.owner),
        staleDays: Math.max(1, Math.floor(ageMs(moved) / (1000 * 60 * 60 * 24))),
        score: 320 + (action.priority === "Critical" ? 40 : action.priority === "High" ? 20 : 0),
      });
    });

    unassignedAccountability.unresolvedProblems.forEach((problem) => {
      const moved = movementDate(problem);
      if (!isStale(moved)) return;
      items.push({
        key: `Problem:${problem.id}`,
        objectType: "Problem",
        id: problem.id,
        title: problem.problemStatement,
        area: getAreaText(problem) || "Unassigned",
        owner: problem.owner || "Unassigned",
        gapLabel: ownershipGapLabel(problem.owner),
        staleDays: Math.max(1, Math.floor(ageMs(moved) / (1000 * 60 * 60 * 24))),
        score: 320 + (problem.severity === "Critical" ? 40 : problem.severity === "High" ? 20 : 0),
      });
    });

    unassignedAccountability.activeProjects.forEach((project) => {
      const moved = movementDate(project);
      if (!isStale(moved)) return;
      items.push({
        key: `Project:${project.id}`,
        objectType: "Project",
        id: project.id,
        title: project.projectName,
        area: project.area || "Unassigned",
        owner: project.owner || "Unassigned",
        gapLabel: ownershipGapLabel(project.owner),
        staleDays: Math.max(1, Math.floor(ageMs(moved) / (1000 * 60 * 60 * 24))),
        score: 330,
      });
    });

    unassignedAccountability.pipelineLeads.forEach((lead) => {
      const moved = lead.followUpDate || lead.dateReceived || lead.dateCreated;
      if (!isStale(moved)) return;
      items.push({
        key: `Lead:${lead.id}`,
        objectType: "Lead",
        id: lead.id,
        title: lead.leadName,
        area: lead.relatedPillar || "Unassigned",
        owner: lead.owner || "Unassigned",
        gapLabel: ownershipGapLabel(lead.owner),
        staleDays: Math.max(1, Math.floor(ageMs(moved) / (1000 * 60 * 60 * 24))),
        score: 300,
      });
    });

    return items.sort((a, b) => b.score - a.score || b.staleDays - a.staleDays);
  })();

  const cashAttention = (() => {
    const now = Date.now();
    const isPast = (dateText?: string) => {
      if (!dateText) return false;
      const parsed = new Date(dateText).getTime();
      return !Number.isNaN(parsed) && parsed < now;
    };

    const cashConfigured = cashAmountsValid;
    const bufferBreached = cashConfigured && availableOperatingCash < 0;
    const bufferPressured = cashConfigured && !bufferBreached && safetyBufferAmount > 0 && availableOperatingCash === 0;

    const buffer = cashConfigured && (bufferBreached || bufferPressured)
      ? {
          key: "Finance:cash-buffer",
          title: bufferBreached ? "Cash below safety buffer" : "Cash at safety buffer",
          detail: bufferBreached
            ? `Available operating cash is ${formatFinanceAmount(availableOperatingCash)}, below the safety buffer of ${formatFinanceAmount(safetyBufferAmount)}.`
            : `Available operating cash is exactly at the safety buffer of ${formatFinanceAmount(safetyBufferAmount)}.`,
          severity: bufferBreached ? "critical" : "high",
        }
      : null;

    const overdueCommitments = commitmentRecords
      // Only a genuine (effectively Committed) obligation being overdue is a real cash-attention issue;
      // an overdue Planned/Quoted figure is a planning miss, not unpaid unavoidable spend.
      .filter((commitment) => getEffectiveCommitmentCertainty(commitment) === "Committed")
      .filter((commitment) => !hasPendingProcurementValidation(commitment))
      .filter((commitment) => getEffectiveProcurementApprovalStatus(commitment) !== "Rejected")
      .filter((commitment) => commitment.status !== "Paid" && commitment.status !== "Cancelled" && (commitment.status === "Overdue" || isPast(commitment.dueDate)))
      .map((commitment) => ({
        key: `Finance:commitment:${commitment.id}`,
        id: commitment.id,
        title: commitment.commitmentName,
        amount: parseFinanceAmount(commitment.amount),
        dueDate: commitment.dueDate,
        detail: `${commitment.type} commitment of ${formatFinanceAmount(parseFinanceAmount(commitment.amount))} was due ${commitment.dueDate || "—"} and is not paid.`,
      }));

    const overdueExpectedIncome = incomeRecords
      .filter((income) => income.status === "Expected" && isPast(income.date))
      .map((income) => ({
        key: `Finance:income:${income.id}`,
        id: income.id,
        title: income.description || income.customerSource || "Expected income",
        amount: parseFinanceAmount(income.amount),
        date: income.date,
        detail: `Expected income of ${formatFinanceAmount(parseFinanceAmount(income.amount))} was due ${income.date || "—"} and has not been received.`,
      }));

    // Reuses the canonical deployable-cash-minus-commitments figure from capitalAllocation (already net of
    // reserved tax, safety buffer, and planning exposure) — this is now a genuine committed-cash shortfall.
    const shortfall = capitalAllocation.uncommittedDeployableCash;
    const fundingGap = shortfall !== null && shortfall < 0
      ? {
          key: "Finance:funding-gap",
          title: "Committed obligations exceed available cash",
          detail: `Committed obligations exceed available operating cash by ${formatFinanceAmount(Math.abs(shortfall))}. Quoted, Planned and Pending validation figures are not included in this shortfall.`,
          amount: Math.abs(shortfall),
        }
      : null;

    return {
      buffer,
      fundingGap,
      overdueCommitments,
      overdueExpectedIncome,
      count: (buffer ? 1 : 0) + (fundingGap ? 1 : 0) + overdueCommitments.length + overdueExpectedIncome.length,
      totalOverdueAmount: overdueCommitments.reduce((sum, item) => sum + item.amount, 0) + overdueExpectedIncome.reduce((sum, item) => sum + item.amount, 0),
    };
  })();

  const growthAttention = (() => {
    const now = Date.now();
    const dayMs = 1000 * 60 * 60 * 24;
    const ageDays = (dateText?: string) => {
      const value = getDateValue(dateText);
      return value > 0 ? Math.floor((now - value) / dayMs) : 0;
    };

    const opportunityThresholdDays = 14;
    const stalledOpportunities = opportunityRecords
      .filter((opportunity) =>
        ["High", "Exceptional"].includes(opportunity.strategicFit) &&
        ["New", "Evaluating"].includes(opportunity.status) &&
        ageDays(opportunity.dateIdentified || opportunity.createdAt) >= opportunityThresholdDays &&
        !decisionRecords.some((decision) => decision.relatedOpportunity === opportunity.id && isDecisionActive(decision)),
      )
      .map((opportunity) => ({
        id: opportunity.id,
        title: opportunity.opportunityTitle || opportunity.title,
        strategicFit: opportunity.strategicFit,
        status: opportunity.status,
        area: getAreaText(opportunity) || "Unassigned",
        ageDays: ageDays(opportunity.dateIdentified || opportunity.createdAt),
        estimatedUpside: parseFinanceAmount(opportunity.estimatedUpside),
      }));

    const newLeadThresholdDays = 7;
    const stalledLeads = activeLeads
      .filter((lead) => !["Won", "Lost"].includes(lead.status))
      .map((lead) => {
        const quoteAmount = parseFinanceAmount(lead.quoteValue);
        const followUpTime = getDateValue(lead.followUpDate);
        const receivedAge = ageDays(lead.dateReceived || lead.dateCreated);

        if (lead.status === "Quote Sent" && !lead.followUpDate) {
          return { lead, quoteAmount, reason: "Quote sent with no follow-up scheduled", ageDays: ageDays(lead.quoteSentDate || lead.dateReceived || lead.dateCreated) };
        }
        if (lead.status === "Quote Sent" && followUpTime > 0 && followUpTime < now) {
          return { lead, quoteAmount, reason: "Follow-up date passed with no resolution", ageDays: ageDays(lead.followUpDate) };
        }
        if (lead.status === "New" && receivedAge >= newLeadThresholdDays) {
          return { lead, quoteAmount, reason: "New lead with no contact progress", ageDays: receivedAge };
        }
        return null;
      })
      .filter((entry): entry is NonNullable<typeof entry> => entry !== null)
      .map((entry) => ({
        id: entry.lead.id,
        title: entry.lead.leadName,
        status: entry.lead.status,
        area: entry.lead.relatedPillar || "Unassigned",
        quoteValue: entry.quoteAmount,
        reason: entry.reason,
        ageDays: entry.ageDays,
      }));

    const stalledQuoteValue = stalledLeads.reduce((sum, item) => sum + item.quoteValue, 0);

    return {
      stalledOpportunities,
      stalledLeads,
      stalledQuoteValue,
      count: stalledOpportunities.length + stalledLeads.length,
    };
  })();

  const selectedAccountability = selectedAccountabilityKey === "unassigned"
    ? unassignedAccountability
    : personAccountabilitySummaries.find((entry) => entry.person.id === selectedAccountabilityKey) ?? null;
  const selectedAccountabilityPerson = selectedAccountability?.person ?? null;
  const selectedPersonDelegationHandoffs = selectedAccountabilityPerson
    ? delegationHandoffFollowThrough.items.filter((handoff) => handoff.newOwnerPersonId === selectedAccountabilityPerson.id || handoff.delegatedByPersonId === selectedAccountabilityPerson.id)
    : [];

  const selectedAccountabilityDetail = selectedAccountability ? (() => {
    const snapshot = selectedAccountability;
    const ownerLabel = snapshot.ownerLabel;
    const hasOwner = snapshot.person !== null;
    const ownerPhrase = hasOwner ? `with ${ownerLabel}` : "without a named owner";
    const gapMeta = (ownerValue?: string) => (hasOwner ? "" : `${ownershipGapLabel(ownerValue)} • `);

    const sections = [
      {
        label: "Overdue actions",
        items: snapshot.overdueActions.map((action) => ({
          id: action.id,
          objectType: "Action",
          title: action.actionTitle,
          meta: `${gapMeta(action.owner)}${action.status} • ${action.priority} priority • Due ${action.dueDate || "not set"}`,
          why: hasOwner
            ? `The due date was ${action.dueDate}. This is still ${action.status.toLowerCase()} and sits ${ownerPhrase}, so delegated delivery is slipping and needs a reset on timing, scope or support.`
            : `The due date was ${action.dueDate}. This action is overdue and has no owner, so it will keep slipping until it is assigned.`,
        })),
      },
      {
        label: "Blocked actions",
        items: snapshot.blockedActions.map((action) => ({
          id: action.id,
          objectType: "Action",
          title: action.actionTitle,
          meta: `${gapMeta(action.owner)}${action.priority} priority • Due ${action.dueDate || "not set"}`,
          why: `This action is blocked ${ownerPhrase}, which means progress depends on removing a dependency before anything else can move.`,
        })),
      },
      {
        label: "Blocked projects",
        items: snapshot.blockedProjects.map((project) => ({
          id: project.id,
          objectType: "Project",
          title: project.projectName,
          meta: `${gapMeta(project.owner)}${project.area || "No area"} • Target ${project.targetCompletionDate || "not set"}`,
          why: `This project is blocked ${ownerPhrase}, so delivery and revenue timing are uncertain until it is unblocked.`,
        })),
      },
      {
        label: "Decisions waiting on them",
        items: snapshot.waitingDecisions.map((decision) => ({
          id: decision.id,
          objectType: "Decision",
          title: decision.decisionTitle,
          meta: `${decision.decisionStatus} • ${decision.riskLevel} risk • Review ${decision.reviewDate || "not set"}`,
          why: decision.decisionStatus === "Draft"
            ? `This decision is still in draft ${ownerPhrase}, so execution is waiting on a choice that has not been finished.`
            : decision.decisionStatus === "Under Review"
              ? `This decision is under review ${ownerPhrase} and needs a conclusion so work can proceed on a settled basis.`
              : `The review date of ${decision.reviewDate} has passed ${ownerPhrase}, so the decision may be stale and needs confirmation or reversal.`,
        })),
      },
      {
        label: "Leads needing follow-up",
        items: snapshot.followUpLeads.map((lead) => ({
          id: lead.id,
          objectType: "Lead",
          title: lead.leadName,
          meta: `${gapMeta(lead.owner)}${lead.status} • ${lead.serviceRequested} • Follow-up ${lead.followUpDate || "not set"}`,
          why: lead.followUpDate && new Date(lead.followUpDate).getTime() <= Date.now()
            ? `The follow-up date was ${lead.followUpDate}. This lead is going stale ${ownerPhrase}, and slow response risks losing the work.`
            : `This lead is marked Follow-Up ${ownerPhrase}, so momentum depends on the next contact happening soon.`,
        })),
      },
      {
        label: "Unresolved problems",
        items: snapshot.unresolvedProblems.map((problem) => ({
          id: problem.id,
          objectType: "Problem",
          title: problem.problemStatement,
          meta: `${gapMeta(problem.owner)}${problem.severity} severity • ${problem.problemStatus}`,
          why: hasOwner
            ? `This problem is still ${problem.problemStatus.toLowerCase()} ${ownerPhrase}, so it continues to affect quality, time or delivery until resolved.`
            : `This problem is still ${problem.problemStatus.toLowerCase()} but has no valid active owner, so accountability for resolving it is not established.`,
        })),
      },
      {
        label: "Active projects",
        items: snapshot.otherActiveProjects.map((project) => ({
          id: project.id,
          objectType: "Project",
          title: project.projectName,
          meta: `${gapMeta(project.owner)}${project.status} • ${project.area || "No area"} • Target ${project.targetCompletionDate || "not set"}`,
          why: hasOwner
            ? `This project is active ${ownerPhrase} and forms part of the current delivery load.`
            : "This project is active but has no valid active owner, so accountability for its delivery is not established.",
        })),
      },
      {
        label: "Other open actions",
        items: snapshot.otherOpenActions.map((action) => ({
          id: action.id,
          objectType: "Action",
          title: action.actionTitle,
          meta: `${gapMeta(action.owner)}${action.status} • ${action.priority} priority • Due ${action.dueDate || "not set"}`,
          why: hasOwner
            ? `This action is part of the current workload ${ownerPhrase} and is proceeding inside normal ownership.`
            : "This action is active but has no valid active owner, so accountability for it is not established.",
        })),
      },
      {
        label: "Other pipeline leads",
        items: snapshot.otherPipelineLeads.map((lead) => ({
          id: lead.id,
          objectType: "Lead",
          title: lead.leadName,
          meta: `${gapMeta(lead.owner)}${lead.status} • ${lead.serviceRequested}`,
          why: hasOwner
            ? `This lead is in the pipeline ${ownerPhrase} and is progressing without an immediate follow-up risk.`
            : "This lead is in the pipeline but has no valid active owner, so accountability for progressing it is not established.",
        })),
      },
    ];

    return { ownerLabel, hasOwner, sections };
  })() : null;

  const metricsOpenOpportunities = opportunityRecords.filter((opportunity) => opportunity.status === "New" || opportunity.status === "Evaluating" || opportunity.status === "On Hold").length;
  const metricsApprovedOpportunities = opportunityRecords.filter((opportunity) => opportunity.status === "Approved").length;
  const metricsActiveDecisions = decisionRecords.filter((decision) => isDecisionActive(decision)).length;
  const metricsLeadsAwaitingFollowUp = activeLeads.filter((lead) => lead.status === "Follow-Up").length;
  const metricsWonLeads = metricsJobsWon;
  const metricsLostLeads = activeLeads.filter((lead) => lead.status === "Lost").length;

  const formatMetricPercent = (value: number) => `${value.toFixed(0)}%`;

  const getAttentionSummary = (item: AttentionItem) => {
    if (item.objectType === "Icarus" && item.strategicRisk) {
      return item.strategicRisk.summary;
    }

    const delegationInterventionReason = item.reasons.find((reason) => reason.startsWith("DELEGATION INTERVENTION REQUIRED"));
    if (delegationInterventionReason) {
      return delegationInterventionReason.includes(": ")
        ? delegationInterventionReason.slice("DELEGATION INTERVENTION REQUIRED: ".length)
        : "Delegated work now needs founder intervention because normal delegated control is no longer sufficient.";
    }

    const delegationReviewReason = item.reasons.find((reason) => reason.startsWith("DELEGATION REVIEW DUE"));
    if (delegationReviewReason) {
      return delegationReviewReason.includes(": ")
        ? delegationReviewReason.slice("DELEGATION REVIEW DUE: ".length)
        : "Delegated work is due for operational review.";
    }

    const delegationRiskReason = item.reasons.find((reason) => reason.startsWith("DELEGATION AT RISK"));
    if (delegationRiskReason) {
      return delegationRiskReason.includes(": ")
        ? delegationRiskReason.slice("DELEGATION AT RISK: ".length)
        : "Delegated work has a recoverable risk signal that needs review.";
    }

    const procurementBlockedReason = item.reasons.find((reason) => reason.startsWith("PROCUREMENT BLOCKED"));
    if (procurementBlockedReason) {
      return procurementBlockedReason.includes(": ")
        ? procurementBlockedReason.slice("PROCUREMENT BLOCKED: ".length)
        : "Purchase is blocked by missing information or a funding gap.";
    }

    const procurementReadyReason = item.reasons.find((reason) => reason.startsWith("PROCUREMENT READY"));
    if (procurementReadyReason) {
      return procurementReadyReason.includes(": ")
        ? procurementReadyReason.slice("PROCUREMENT READY: ".length)
        : "Purchase is ready for founder commitment.";
    }

    const blockerReason = item.reasons.find((reason) => reason.startsWith("BLOCKED BY PROBLEM: "));
    if (blockerReason) {
      return `Blocked by unresolved problem: ${blockerReason.slice("BLOCKED BY PROBLEM: ".length)}.`;
    }

    const decisionReason = item.reasons.find((reason) => reason.startsWith("WAITING ON DECISION: "));
    if (decisionReason) {
      return `Waiting on active decision: ${decisionReason.slice("WAITING ON DECISION: ".length)}.`;
    }

    const overdueReason = item.reasons.find((reason) => reason.startsWith("OVERDUE BY "));
    if (overdueReason && item.objectType === "Action") {
      const days = overdueReason.replace("OVERDUE BY ", "").replace(/ DAY(S)?$/, "");
      return `Overdue by ${days} day${days === "1" ? "" : "s"} and still ${item.statusText.split(" /")[0].toLowerCase()}.`;
    }

    if (item.objectType === "Problem" && item.reasons.some((reason) => reason.includes("SEVERITY"))) {
      return `${item.statusText.split(" /")[0]}-severity problem remains unresolved.`;
    }

    if (item.objectType === "Decision" && item.reasons.includes("REVIEW DUE")) {
      return "Decision review date has been reached.";
    }

    if (item.objectType === "Action" && item.reasons.some((reason) => reason.endsWith("PRIORITY"))) {
      return "High-priority action is still active.";
    }

    if (item.objectType === "Opportunity" && item.reasons.some((reason) => reason.startsWith("STRATEGIC FIT:"))) {
      return "High strategic-fit opportunity is still under evaluation.";
    }

    if (item.objectType === "Project") {
      if (item.reasons.includes("BLOCKED PROJECT")) return "Project is currently blocked and requires status review.";
      if (item.reasons.includes("OVERDUE PROJECT")) return "Project target completion date has passed.";
      if (item.reasons.includes("DUE WITHIN 7 DAYS")) return "Project target completion date is approaching.";
      if (item.reasons.includes("PAST START DATE • NOT STARTED")) return "Project start date has passed and work has not started.";
    }

    return `${item.objectType} remains ${item.statusText.split(" /")[0].toLowerCase()}.`;
  };

  const getProjectIssueSummary = (item: AttentionItem) => {
    if (item.objectType !== "Project") {
      return null;
    }

    const overdueReason = item.reasons.find((reason) => /^\d+ DAYS? OVERDUE$/.test(reason));
    const overdueDays = overdueReason?.match(/^\d+/)?.[0];
    return [
      item.reasons.includes("BLOCKED PROJECT") ? "Blocked" : null,
      overdueDays ? `${overdueDays} day${overdueDays === "1" ? "" : "s"} overdue` : null,
      item.reasons.includes("DUE WITHIN 7 DAYS") ? "Due soon" : null,
      item.reasons.includes("PAST START DATE • NOT STARTED") ? "Past start date" : null,
    ].filter(Boolean).join(" • ");
  };

  const getProjectAttentionAge = (item: AttentionItem) => {
    if (item.objectType !== "Project" || !item.targetCompletionDate) {
      return null;
    }

    const targetCompletionDate = new Date(`${item.targetCompletionDate}T00:00:00`);
    if (Number.isNaN(targetCompletionDate.getTime())) {
      return null;
    }

    const today = new Date();
    today.setHours(0, 0, 0, 0);
    const daysFromToday = Math.round((targetCompletionDate.getTime() - today.getTime()) / (1000 * 60 * 60 * 24));
    if (item.reasons.includes("OVERDUE PROJECT") && daysFromToday < 0) {
      const days = Math.abs(daysFromToday);
      return `Overdue for ${days} day${days === 1 ? "" : "s"}`;
    }

    if (item.reasons.includes("DUE WITHIN 7 DAYS") && daysFromToday >= 0) {
      return `Due in ${daysFromToday} day${daysFromToday === 1 ? "" : "s"}`;
    }

    return null;
  };

  const getProjectTargetDateState = (item: AttentionItem) => {
    if (item.objectType !== "Project" || !item.targetCompletionDate) {
      return "No target date";
    }

    const targetCompletionDate = new Date(`${item.targetCompletionDate}T00:00:00`);
    if (Number.isNaN(targetCompletionDate.getTime())) {
      return "No target date";
    }

    const today = new Date();
    today.setHours(0, 0, 0, 0);
    const daysFromToday = Math.round((targetCompletionDate.getTime() - today.getTime()) / (1000 * 60 * 60 * 24));
    if (daysFromToday < 0) return "Overdue";
    if (daysFromToday === 0) return "Due today";
    if (daysFromToday <= 7) return "Due soon";
    return "Due later";
  };

  const getActionDependencyBlocker = (action: ActionRecord) => {
    const blocker = getActionDependencyBlockerRule(action, problemRecords, decisionRecords);
    if (!blocker) return null;

    if (blocker.objectType === "Problem") {
      const relatedProblem = problemRecords.find((problem) => problem.id === blocker.id);
      if (!relatedProblem) return null;
      return {
        ...blocker,
        onOpen: () => {
          setSelectedProblemId(relatedProblem.id);
          setProblemEditor(relatedProblem);
        },
      };
    }

    const relatedDecision = decisionRecords.find((decision) => decision.id === blocker.id);
    if (!relatedDecision) return null;
    return {
      ...blocker,
      onOpen: () => {
        setSelectedDecisionId(relatedDecision.id);
        setDecisionEditor(relatedDecision);
      },
    };
  };

  const executableAction = (action: ActionRecord) => isActionActive(action) && !isActionWaiting(action) && action.status !== "Blocked"
    && !getActionDependencyBlocker(action)
    && (!action.earliestExecutableDate || new Date(`${action.earliestExecutableDate.slice(0, 10)}T00:00:00`).getTime() <= new Date().setHours(0, 0, 0, 0));

  const strategicAssessments = strategicObjectives.map((objective) => {
    const linkedProjects = projects.filter((project) => objective.linkedProjectIds.includes(project.id));
    const linkedOpportunities = opportunityRecords.filter((opportunity) => objective.linkedOpportunityIds.includes(opportunity.id));
    const linkedDecisions = decisionRecords.filter((decision) => objective.linkedDecisionIds.includes(decision.id));
    const activeProjects = linkedProjects.filter(isProjectActive);
    const activeOpportunities = linkedOpportunities.filter((opportunity) => ["New", "Evaluating", "Approved"].includes(opportunity.status));
    const activeDecisions = linkedDecisions.filter((decision) => ["Active", "Under Review"].includes(decision.decisionStatus));
    const hasLinkedPath = linkedProjects.length + linkedOpportunities.length + linkedDecisions.length > 0;
    const hasActivePath = activeProjects.length + activeOpportunities.length + activeDecisions.length > 0;
    const hasExecutablePath = activeProjects.some((project) => (project.relatedActionIds || []).some((id) => actionRecords.some((action) => action.id === id && executableAction(action))))
      || linkedOpportunities.some((opportunity) => opportunity.status === "Approved")
      || activeDecisions.some((decision) => actionRecords.some((action) => action.relatedDecision === decision.id && executableAction(action)));
    const gaps: string[] = [];
    if (objective.status === "Active" && objective.horizon === "Now" && !hasLinkedPath) gaps.push("Active Now objective has no linked Project, Opportunity or Decision.");
    if (objective.status === "Active" && ["Critical", "High"].includes(objective.importance) && !hasActivePath) gaps.push("High-importance objective has no active execution path.");
    if (objective.status === "Active" && objective.founderAllocation === "Founder attention now" && !hasExecutablePath) gaps.push("Founder attention is needed, but no executable linked path is recorded.");
    if (objective.founderAllocation === "Parked" && activeProjects.length) gaps.push("Parked objective still has active linked Projects.");
    return { objective, linkedProjects, linkedOpportunities, linkedDecisions, gaps, hasExecutablePath };
  });
  const unlinkedStrategicProjects = projects.filter((project) => isProjectActive(project) && !strategicObjectives.some((objective) => objective.linkedProjectIds.includes(project.id)));

  const commandLearningInput = buildOrganisationalLearning({
    actions: actionRecords,
    projects,
    decisions: decisionRecords.map((decision) => ({
      ...decision,
      executionState: deriveDecisionExecutionState(decision, actionRecords, projects).state,
    })),
    lessons: lessonRecords,
    problems: problemRecords.map((problem) => ({
      ...problem,
      isUnresolved: isProblemUnresolved(problem),
    })),
    systems: systemRecords,
    sops: sopRecords,
    icarusTreatmentOutcomes: icarusInterventionIndex.learningInput,
    icarusLifecycle: icarusInterventionIndex.lifecycle,
  }).map((signal) => ({ signal }));

  const commandAttentionPolicy = buildCommandAttention({
    problems: problemRecords,
    actions: actionRecords,
    outreach: outreachContacts,
    projects,
    decisions: decisionRecords,
    opportunities: opportunityRecords,
    lessons: lessonRecords,
    systems: systemRecords,
    sops: sopRecords,
    handoffs: delegationHandoffFollowThrough.items.map((handoff) => ({
      objectType: handoff.objectType,
      objectId: handoff.objectId,
      title: handoff.title,
      newOwner: handoff.newOwner,
      newOwnerPersonId: handoff.newOwnerPersonId,
      transferredAt: handoff.transferredAt,
      reviewDate: handoff.reviewDate,
      reviewState: handoff.reviewState,
      reviewReasons: handoff.reviewReasons,
      area: handoff.area,
      targetCompletionDate: handoff.objectType === "Project"
        ? projects.find((project) => project.id === handoff.objectId)?.targetCompletionDate
        : undefined,
    })),
    procurementQueue: capitalAllocation.procurementQueue,
    learning: commandLearningInput,
    icarus: icarusSignalsWithTreatment,
    nowMs: Date.now(),
  });
  const toCommandAttentionItem = (item: CommandAttentionItem): AttentionItem => {
    const dependencyAction = item.dependencyAction;
    const strategicRiskReference = item.strategicRisk?.references[0];
    return {
      ...item,
      onOpen: () => {
        if (item.objectType === "Icarus" && strategicRiskReference) {
          openIcarusReference(strategicRiskReference);
        } else if (item.navigationMode === "record-handler") {
          handleOpenAttentionRecord(item.objectType, item.id);
        } else if (item.objectType === "Problem") {
          const record = problemRecords[item.sourceIndex ?? -1];
          if (record?.id === item.id) {
            setSelectedProblemId(record.id);
            setProblemEditor(record);
          }
        } else if (item.objectType === "Action") {
          const record = actionRecords[item.sourceIndex ?? -1];
          if (record?.id === item.id) {
            setSelectedActionId(record.id);
            setActionEditor(record);
          }
        } else if (item.objectType === "Project") {
          const record = projects[item.sourceIndex ?? -1];
          if (record?.id === item.id) handleProjectEditOpen(record);
        } else if (item.objectType === "Decision") {
          const record = decisionRecords[item.sourceIndex ?? -1];
          if (record?.id === item.id) {
            setSelectedDecisionId(record.id);
            setDecisionEditor(record);
          }
        } else if (item.objectType === "Opportunity") {
          const record = opportunityRecords[item.sourceIndex ?? -1];
          if (record?.id === item.id) {
            setSelectedOpportunityId(record.id);
            setOpportunityEditor(record);
          }
        } else if (item.objectType === "Lesson") {
          const record = lessonRecords[item.sourceIndex ?? -1];
          if (record?.id === item.id) {
            setSelectedLessonId(record.id);
            setLessonEditor(record);
          }
        } else if (item.objectType === "System") {
          const record = systemRecords[item.sourceIndex ?? -1];
          if (record?.id === item.id) {
            setSelectedSystemId(record.id);
            setSystemEditor(record);
          }
        } else if (item.objectType === "SOP") {
          const record = sopRecords[item.sourceIndex ?? -1];
          if (record?.id === item.id) {
            setSelectedSopId(record.id);
            setSopEditor(record);
          }
        } else {
          handleOpenAttentionRecord(item.objectType, item.id);
        }
      },
      dependencyAction: dependencyAction ? {
        label: dependencyAction.label,
        onOpen: () => {
          const target = dependencyAction.target;
          if (target.kind === "accountability") {
            setActiveView("People");
            setSelectedAccountabilityKey(target.personId);
          } else {
            handleOpenAttentionRecord(target.objectType, target.id);
          }
        },
      } : undefined,
      strategicRiskAction: item.objectType !== "Icarus" && strategicRiskReference ? {
        label: `${item.strategicRisk && item.strategicRisk.references.length > 1
          ? `Open Icarus risks (${item.strategicRisk.references.length})`
          : "Open Icarus risk"}${item.convergentStrategicRisk ? " · convergent risk" : ""}`,
        onOpen: () => openIcarusReference(strategicRiskReference),
      } : undefined,
    };
  };
  // Pre-correlation Command list: feeds the correlation graph and other inputs computed before convergence is known.
  const baseCommandAttentionItemList: AttentionItem[] = commandAttentionPolicy.items.map(toCommandAttentionItem);

  type FounderCapitalAttentionItem = {
    key: string;
    objectId: string;
    title: string;
    amount: number | null;
    readinessState?: ProcurementReadinessState;
    approvalStatus?: ProcurementApprovalStatus;
    quoteState?: ProcurementQuoteState | null;
    reason: string;
    nextAction: string;
    area: string;
    date: string;
    rank: number;
    sortDate: number;
  };
  const founderCapitalAttention = (() => {
    const itemsByKey = new Map<string, FounderCapitalAttentionItem>();
    const addItem = (item: FounderCapitalAttentionItem) => {
      const existing = itemsByKey.get(item.key);
      if (!existing || item.rank < existing.rank) itemsByKey.set(item.key, item);
    };
    const todayMs = new Date().setHours(0, 0, 0, 0);
    const sevenDaysFromTodayMs = todayMs + (7 * 24 * 60 * 60 * 1000);
    const isTimeSensitive = (date: string) => {
      const dateValue = getDateValue(date);
      return dateValue > 0 && dateValue <= sevenDaysFromTodayMs;
    };
    const isMaterial = (amount: number) =>
      amount > 0
      && capitalAllocation.uncommittedDeployableCash !== null
      && amount >= Math.max(0, capitalAllocation.uncommittedDeployableCash);

    if (cashAttention.fundingGap) {
      addItem({
        key: "Finance:funding-gap",
        objectId: "funding-gap",
        title: cashAttention.fundingGap.title,
        amount: cashAttention.fundingGap.amount,
        reason: cashAttention.fundingGap.detail,
        nextAction: "Review committed obligations and restore deployable cash.",
        area: "Finance",
        date: "",
        rank: 1,
        sortDate: 0,
      });
    }
    if (cashAttention.buffer) {
      addItem({
        key: "Finance:cash-buffer",
        objectId: "cash-buffer",
        title: cashAttention.buffer.title,
        amount: capitalAllocation.uncommittedDeployableCash,
        reason: cashAttention.buffer.detail,
        nextAction: "Review the cash snapshot, protected cash and near-term obligations.",
        area: "Finance",
        date: "",
        rank: 1,
        sortDate: 0,
      });
    }

    capitalAllocation.procurementQueue.forEach((item) => {
      if (item.isRejected || item.isPurchased) return;
      const date = item.commitment.expectedPurchaseDate || item.commitment.dueDate || "";
      const deferredUntilValue = getDateValue(item.commitment.capitalDecisionDeferredUntil);
      const isActivelyDeferred = item.commitment.capitalDecisionOutcome === "Defer" && deferredUntilValue > todayMs;
      const timeSensitive = isTimeSensitive(date);
      const material = isMaterial(item.amountRequired);
      const approvedDependency = item.approvalStatus === "Approved"
        && (item.readinessState === "Blocked" || item.readinessState === "Pending validation");
      const readyAwaitingReview = item.readinessState === "Ready to buy" && item.approvalStatus === "Not reviewed";
      const approvedAwaitingCommitment = item.readinessState === "Ready to buy"
        && item.approvalStatus === "Approved"
        && !item.isCommitted;
      const judgementRequired = ["Planned", "Quoted"].includes(item.effectiveCertainty)
        && item.approvalStatus === "Not reviewed"
        && item.commitment.capitalDecisionOutcome !== "Mark Pending validation"
        && (timeSensitive || material);
      const quoteIssueNeedsAttention = (item.quoteState === "Expired" || item.quoteState === "Expiring soon")
        && (timeSensitive || material)
        && (item.approvalStatus === "Approved" || item.readinessState === "Ready to buy" || item.readinessState === "Pending validation");
      const committedFundingPressure = Boolean(cashAttention.fundingGap) && item.isCommitted;
      const overdueUrgency = Boolean(date) && getDateValue(date) < todayMs;

      if (isActivelyDeferred && !committedFundingPressure && !overdueUrgency) return;
      if (!approvedDependency && !(readyAwaitingReview && (timeSensitive || material)) && !approvedAwaitingCommitment && !judgementRequired && !quoteIssueNeedsAttention && !committedFundingPressure) return;

      const baseReason = committedFundingPressure
        ? "This committed purchase contributes to the current funding gap."
        : approvedDependency
          ? `Capital is approved, but execution cannot proceed: ${item.readinessReason}`
          : readyAwaitingReview
            ? "The purchase is operationally ready, but capital has not been formally reviewed."
            : approvedAwaitingCommitment
              ? "Capital is approved and the purchase is ready, but funds have not been committed."
              : material
                ? "Founder judgement is required because this planned exposure would consume current uncommitted deployable cash."
                : "Founder judgement is required before the time-sensitive planned exposure can be committed.";
      const quoteReason = item.quoteState === "Expired"
        ? `The quoted price expired on ${item.commitment.quoteExpiryDate}.`
        : item.quoteState === "Expiring soon"
          ? `The quoted price expires soon on ${item.commitment.quoteExpiryDate}.`
          : "";
      const reason = quoteIssueNeedsAttention && !baseReason.toLowerCase().includes(item.quoteState === "Expired" ? "expired" : "expires soon")
        ? `${baseReason} ${quoteReason}`
        : baseReason;
      const baseNextAction = committedFundingPressure
        ? "Review this commitment against the funding gap."
        : approvedDependency
          ? item.readinessState === "Pending validation" ? "Confirm the external dependency and clear Pending validation." : "Resolve the cash or information blocker."
          : readyAwaitingReview
            ? "Review and approve or reject the purchase."
            : approvedAwaitingCommitment
              ? "Commit the approved funds or revise the approval."
              : "Review the quote or plan and approve, reject or defer it.";
      const nextAction = quoteIssueNeedsAttention
        ? `Revalidate or replace the quoted price. ${baseNextAction}`
        : baseNextAction;

      addItem({
        key: `Finance:commitment:${item.commitment.id}`,
        objectId: `commitment:${item.commitment.id}`,
        title: item.commitment.commitmentName,
        amount: item.amountRequired,
        readinessState: item.readinessState,
        approvalStatus: item.approvalStatus,
        quoteState: item.quoteState,
        reason,
        nextAction,
        area: item.commitment.relatedPillar,
        date,
        rank: committedFundingPressure ? 1 : approvedDependency ? 2 : readyAwaitingReview ? 3 : approvedAwaitingCommitment ? 4 : 5,
        sortDate: getDateValue(date),
      });
    });

    const procurementCommitmentIds = new Set(capitalAllocation.procurementItems.map((item) => item.commitment.id));
    capitalAllocation.validActiveCommitments.forEach((item) => {
      if (procurementCommitmentIds.has(item.commitment.id) || item.isRejected || item.amount === null || !isMaterial(item.amount)) return;
      const date = item.commitment.dueDate || "";
      const deferredUntilValue = getDateValue(item.commitment.capitalDecisionDeferredUntil);
      if (item.commitment.capitalDecisionOutcome === "Defer" && deferredUntilValue > todayMs && getDateValue(date) >= todayMs) return;
      addItem({
        key: `Finance:commitment:${item.commitment.id}`,
        objectId: `commitment:${item.commitment.id}`,
        title: item.commitment.commitmentName,
        amount: item.amount,
        approvalStatus: item.approvalStatus,
        reason: "This upcoming commitment materially reduces the current uncommitted deployable cash position.",
        nextAction: "Review timing, necessity and funding coverage before the due date.",
        area: item.commitment.relatedPillar,
        date,
        rank: 5,
        sortDate: getDateValue(date),
      });
    });

    cashAttention.overdueCommitments.forEach((item) => {
      const commitment = commitmentRecords.find((record) => record.id === item.id);
      if (!commitment || getEffectiveProcurementApprovalStatus(commitment) === "Rejected") return;
      addItem({
        key: `Finance:commitment:${item.id}`,
        objectId: `commitment:${item.id}`,
        title: item.title,
        amount: item.amount,
        reason: item.detail,
        nextAction: "Review the overdue obligation and record payment or revised timing.",
        area: commitment.relatedPillar,
        date: item.dueDate,
        rank: 5,
        sortDate: getDateValue(item.dueDate),
      });
    });
    cashAttention.overdueExpectedIncome.forEach((item) => {
      const income = incomeRecords.find((record) => record.id === item.id);
      addItem({
        key: `Finance:income:${item.id}`,
        objectId: `income:${item.id}`,
        title: item.title,
        amount: item.amount,
        reason: item.detail,
        nextAction: "Confirm receipt timing or follow up on the overdue income.",
        area: income?.area || "Finance",
        date: item.date,
        rank: 5,
        sortDate: getDateValue(item.date),
      });
    });

    return [...itemsByKey.values()].sort((left, right) =>
      left.rank - right.rank
      || (left.sortDate || Number.POSITIVE_INFINITY) - (right.sortDate || Number.POSITIVE_INFINITY)
      || (right.amount ?? 0) - (left.amount ?? 0)
      || left.title.localeCompare(right.title),
    );
  })();

  const staleRecords = baseCommandAttentionItemList.filter((item) =>
    item.reasons.some((reason) => reason === "STALE PROJECT" || reason === "STALE PROJECT • TARGET APPROACHING" || reason === "STALE IN-PROGRESS ACTION"),
  );

  const currentRiskSummary = (() => {
    const areaSignals = new Map<string, Map<string, Set<string>>>();
    const addAreaSignal = (areaValue: string | undefined, category: string, objectType: string, id: string) => {
      const area = areaValue?.trim() || "Unassigned";
      if (!areaSignals.has(area)) areaSignals.set(area, new Map());
      const categories = areaSignals.get(area)!;
      if (!categories.has(category)) categories.set(category, new Set());
      categories.get(category)!.add(`${objectType}:${id}`);
    };

    problemRecords
      .filter((problem) => isProblemUnresolved(problem) && ["High", "Critical"].includes(problem.severity))
      .forEach((problem) => addAreaSignal(getAreaText(problem), "High/Critical problems", "Problem", problem.id));
    actionRecords
      .filter((action) => isActionActive(action) && action.status === "Blocked")
      .forEach((action) => addAreaSignal(action.relatedPillar, "Blocked actions", "Action", action.id));
    baseCommandAttentionItemList
      .filter((item) => item.objectType === "Action" && item.reasons.some((reason) => reason.startsWith("OVERDUE BY ")))
      .forEach((item) => addAreaSignal(item.area, "Overdue actions", item.objectType, item.id));
    baseCommandAttentionItemList
      .filter((item) => item.objectType === "Project")
      .forEach((item) => {
        if (item.reasons.includes("BLOCKED PROJECT")) addAreaSignal(item.area, "Blocked projects", item.objectType, item.id);
        if (item.reasons.includes("OVERDUE PROJECT")) addAreaSignal(item.area, "Overdue projects", item.objectType, item.id);
        if (item.reasons.includes("DUE WITHIN 7 DAYS")) addAreaSignal(item.area, "Projects due soon", item.objectType, item.id);
        if (item.reasons.some((reason) => reason.startsWith("STALE PROJECT"))) addAreaSignal(item.area, "Stale projects", item.objectType, item.id);
        if (item.reasons.includes("PAST START DATE • NOT STARTED")) addAreaSignal(item.area, "Projects past start date", item.objectType, item.id);
      });
    decisionTrackRecord.reviewsDue.forEach((decision) =>
      addAreaSignal(getAreaText(decision), "Decision reviews due", "Decision", decision.id));
    decisionsWithoutExecution.forEach((decision) =>
      addAreaSignal(decision.area, "Decisions without execution", "Decision", decision.id));
    recurringProblemLearning.unresolvedRecurring.forEach((problem) =>
      addAreaSignal(getAreaText(problem), "Recurring unresolved problems", "Problem", problem.id));
    recurringProblemLearning.gaps.forEach((problem) =>
      addAreaSignal(problem.area, "Recurring-learning gaps", "Problem", problem.id));
    unassignedAccountability.ownedActions.forEach((action) =>
      addAreaSignal(action.relatedPillar, "Ownership gaps", "Action", action.id));
    unassignedAccountability.activeProjects.forEach((project) =>
      addAreaSignal(project.area, "Ownership gaps", "Project", project.id));
    unassignedAccountability.pipelineLeads.forEach((lead) =>
      addAreaSignal(lead.relatedPillar, "Ownership gaps", "Lead", lead.id));
    unassignedAccountability.unresolvedProblems.forEach((problem) =>
      addAreaSignal(getAreaText(problem), "Ownership gaps", "Problem", problem.id));
    unassignedAccountability.waitingDecisions.forEach((decision) =>
      addAreaSignal(getAreaText(decision), "Ownership gaps", "Decision", decision.id));
    growthAttention.stalledOpportunities.forEach((opportunity) =>
      addAreaSignal(opportunity.area, "Stalled high-fit opportunities", "Opportunity", opportunity.id));
    growthAttention.stalledLeads.forEach((lead) =>
      addAreaSignal(lead.area, "Stalled leads", "Lead", lead.id));
    cashAttention.overdueCommitments.forEach((item) => {
      const commitment = commitmentRecords.find((record) => record.id === item.id);
      addAreaSignal(commitment?.relatedPillar, "Overdue commitments", "Finance", item.id);
    });
    cashAttention.overdueExpectedIncome.forEach((item) => {
      const income = incomeRecords.find((record) => record.id === item.id);
      addAreaSignal(income?.area, "Overdue expected income", "Finance", item.id);
    });

    const byArea = [...areaSignals.entries()]
      .map(([area, categories]) => {
        const categoryCounts = [...categories.entries()]
          .map(([label, records]) => ({ label, count: records.size }))
          .sort((left, right) => right.count - left.count || left.label.localeCompare(right.label));
        return {
          area,
          categories: categoryCounts,
          signalCount: categoryCounts.reduce((sum, category) => sum + category.count, 0),
        };
      })
      .sort((left, right) => right.signalCount - left.signalCount || left.area.localeCompare(right.area));

    const empireWide: Array<{ label: string; detail: string }> = [];
    if (organisationalHealth.delegationQuality.label === "Needs attention" && organisationalHealth.selfSufficiencyPct !== null) {
      empireWide.push({
        label: "Founder dependency",
        detail: `${organisationalHealth.selfSufficiencyPct}% of validly owned active work is owned outside the primary Founder; ${operationalIndependence.operationalIndependencePct ?? 0}% can run without routine Founder intervention; the top owner carries ${organisationalHealth.topOwnerShare ?? 0}%${empireDecisionQueue.delegateItems.length > 0 && empireDecisionQueue.delegationCapacityNames.length === 0 ? `; ${empireDecisionQueue.delegateItems.length} founder-owned item${empireDecisionQueue.delegateItems.length === 1 ? " is" : "s are"} suitable for delegation, but ${empireDecisionQueue.delegationReadinessGapNames.length > 0 ? `${empireDecisionQueue.delegationReadinessGapNames.length} active operational delegation person${empireDecisionQueue.delegationReadinessGapNames.length === 1 ? " is" : "s are"} not yet delegation-ready` : "no active operational delegation person is available"}.` : "."}`,
      });
    }
    if (cashAttention.buffer) {
      empireWide.push({ label: "Cash buffer pressure", detail: cashAttention.buffer.detail });
    }
    if (capitalAllocation.uncommittedDeployableCash !== null && capitalAllocation.uncommittedDeployableCash < 0) {
      empireWide.push({
        label: "Committed cash pressure",
        detail: `Committed obligations exceed gross deployable cash by ${formatFinanceAmount(Math.abs(capitalAllocation.uncommittedDeployableCash))}.`,
      });
    }

    return { byArea, empireWide };
  })();

  const correlationLayer = buildCorrelationGraph({
    founderAuthorityItems: empireDecisionQueue.founderAuthorityItems.map(({ objectType, id, title, pillar }) => ({ objectType, id, title, pillar })),
    // Operational priority only: strategic-risk enrichment must not change which record roots a situation.
    commandAttentionItems: baseCommandAttentionItemList.map(({ objectType, id, title, area, reasons, priorityScore, operationalPriorityScore }) => ({ objectType, id, title, area, reasons, priorityScore: operationalPriorityScore ?? priorityScore })),
    decisionReviewsDue: decisionTrackRecord.reviewsDue.map(({ id, decisionTitle, title, relatedArea, relatedPillar, area }) => ({ id, decisionTitle, title, relatedArea, relatedPillar, area })),
    decisionsWithoutExecution: decisionsWithoutExecution.map(({ id, title, area }) => ({ id, title, area })),
    learningGaps: recurringProblemLearning.gaps.map(({ id, title, area }) => ({ id, title, area })),
    staleUnownedWork: staleUnownedWork.map(({ key, objectType, id, title, area, score }) => ({ key, objectType, id, title, area, score })),
    staleRecords: staleRecords.map(({ objectType, id, title, area }) => ({ objectType, id, title, area })),
    stalledOpportunities: growthAttention.stalledOpportunities.map(({ id, title, area, strategicFit }) => ({ id, title, area, strategicFit })),
    stalledLeads: growthAttention.stalledLeads.map(({ id, title, area, quoteValue }) => ({ id, title, area, quoteValue })),
    cashBuffer: cashAttention.buffer ? { title: cashAttention.buffer.title, severity: cashAttention.buffer.severity } : null,
    fundingGap: cashAttention.fundingGap ? { title: cashAttention.fundingGap.title } : null,
    overdueCommitments: cashAttention.overdueCommitments.map(({ id, title }) => ({ id, title })),
    overdueExpectedIncome: cashAttention.overdueExpectedIncome.map(({ id, title }) => ({ id, title })),
    captures: captures.map(({ id }) => ({ id })),
    problems: problemRecords.map(({ id, sourceCaptureId, relatedCapture }) => ({ id, sourceCaptureId, relatedCapture })),
    actions: actionRecords.map(({ id, sourceCaptureId, relatedCapture, relatedProblem, relatedDecision, relatedOpportunity }) => ({ id, sourceCaptureId, relatedCapture, relatedProblem, relatedDecision, relatedOpportunity })),
    decisions: decisionRecords.map(({ id, sourceCaptureId, relatedCapture, relatedOpportunity }) => ({ id, sourceCaptureId, relatedCapture, relatedOpportunity })),
    opportunities: opportunityRecords.map(({ id, sourceCaptureId, relatedCapture }) => ({ id, sourceCaptureId, relatedCapture })),
    lessons: lessonRecords.map(({ id, sourceCaptureId, relatedCapture, relatedProblem, relatedDecision, relatedProject, relatedSystem }) => ({ id, sourceCaptureId, relatedCapture, relatedProblem, relatedDecision, relatedProject, relatedSystem })),
    systems: systemRecords.map(({ id, sourceCaptureId, relatedCapture, relatedLesson }) => ({ id, sourceCaptureId, relatedCapture, relatedLesson })),
    sops: sopRecords.map(({ id, sourceCaptureId, relatedCapture, relatedSystem, relatedLesson }) => ({ id, sourceCaptureId, relatedCapture, relatedSystem, relatedLesson })),
    projects: projects.map(({ id, sourceCaptureId, relatedActionIds, relatedDecisionIds, relatedSystemIds, relatedSopIds }) => ({ id, sourceCaptureId, relatedActionIds, relatedDecisionIds, relatedSystemIds, relatedSopIds })),
    leads: leads.map(({ id }) => ({ id })),
    strategicRisks: icarusIntelligence.correlationSignals,
    contextRecords: buildPeopleCorrelationContext({
      people: people.map(({ id, name, status }) => ({ id, name, status })),
      primaryFounderId: founderPerson?.id ?? null,
      founderDependentWork,
      capabilityGaps: delegationReadinessGapPeople.map((person) => ({
        personId: person.id,
        missingFields: getDelegationReadinessMissingFields(person),
      })),
    }),
  });
  // Icarus Stage B: consumes the graph built from Stage A's correlation signals (verified by the pipeline).
  const icarusCorrelation = buildIcarusCorrelationIntelligence(icarusIntelligence, {
    graph: correlationLayer,
    pillars: pillarOptions,
    recordPillars: [
      ...projects.map((project) => ({ objectType: "Project", id: project.id, pillar: project.area })),
      ...actionRecords.map((action) => ({ objectType: "Action", id: action.id, pillar: getAreaText(action) })),
      ...problemRecords.map((problem) => ({ objectType: "Problem", id: problem.id, pillar: getAreaText(problem) })),
      ...decisionRecords.map((decision) => ({ objectType: "Decision", id: decision.id, pillar: getAreaText(decision) })),
      ...opportunityRecords.map((opportunity) => ({ objectType: "Opportunity", id: opportunity.id, pillar: getAreaText(opportunity) })),
      ...leads.map((lead) => ({ objectType: "Lead", id: lead.id, pillar: lead.relatedPillar || "" })),
    ],
  });

  // Command shows a strategic risk once: folded into a convergent situation's host when one is in Command,
  // otherwise standalone. Same resolution Founder Focus applies.
  const commandAttentionItemList: AttentionItem[] = resolveCommandStrategicRiskConvergence(
    commandAttentionPolicy.items,
    icarusCorrelation.strategicRiskConvergence,
    // Finance items are hidden from the Command display, so they cannot host a folded risk.
    { isEligibleHost: (item) => item.objectType !== "Finance" },
  ).map(toCommandAttentionItem);

  const founderFocusRecordFacts = new Map<string, FounderFocusRecordFact>();
  const addFounderFocusRecordFact = (objectType: string, id: string, dateValue?: string, isWaitingAction = false) => {
    const key = `${objectType}:${id}`;
    if (founderFocusRecordFacts.has(key)) return;
    const timestamp = dateValue ? getDateValue(dateValue) : 0;
    founderFocusRecordFacts.set(key, { urgencyTime: timestamp > 0 ? timestamp : null, isWaitingAction });
  };
  actionRecords.forEach((action) => addFounderFocusRecordFact("Action", action.id, action.dueDate, isActionWaiting(action)));
  projects.forEach((project) => addFounderFocusRecordFact("Project", project.id, project.targetCompletionDate));
  decisionRecords.forEach((decision) => addFounderFocusRecordFact("Decision", decision.id, decision.reviewDate));
  commitmentRecords.forEach((commitment) => addFounderFocusRecordFact("Finance", `commitment:${commitment.id}`, commitment.dueDate));
  incomeRecords.forEach((income) => addFounderFocusRecordFact("Finance", `income:${income.id}`, income.date));

  const founderFocusCandidates = buildFounderFocus({
    signalledRecords: [...correlationLayer.signalled.entries()].map(([recordKey, record]) => ({
      recordKey,
      objectType: record.objectType,
      id: record.id,
      title: record.title,
      area: record.area,
      signals: [...record.signals],
      baseScore: record.baseScore,
    })),
    founderReviewItems: empireDecisionQueue.founderReviewQueue.map(({ objectType, id, title, pillar, reasonCategory, whyItMatters }) => ({
      objectType, id, title, pillar, reasonCategory, whyItMatters,
    })),
    limitations: strategicDataConfidence.limitations.map(({ key, severity, label, action }) => ({
      key,
      severity,
      label,
      action: action ? { objectType: action.objectType, id: action.id } : undefined,
    })),
    convergentRisks: correlationLayer.convergentRisks.map((cluster) => ({
      clusterKey: cluster.clusterKey,
      title: cluster.title,
      records: cluster.records.map(({ recordKey, objectType, id, area, baseScore }) => ({
        recordKey, objectType, id, area, baseScore,
      })),
      categories: [...cluster.categories],
      recordCount: cluster.recordCount,
      rootRecordKey: cluster.rootRecordKey,
    })),
    recordFacts: founderFocusRecordFacts,
    strategicRisks: icarusIntelligence.founderFocusRisks.map((risk) => {
      const treatment = icarusTreatmentIndex.summaries.get(risk.id);
      return treatment ? {
        ...risk,
        treatmentReasons: [
          ...treatment.attentionReasons,
          ...(icarusInterventionIndex.attentionByAssessmentId.get(risk.id) ?? []),
        ],
        founderOwnedTreatmentCount: treatment.founderOwnedCount,
        delegatedTreatmentCount: treatment.delegatedCount,
      } : risk;
    }),
  });
  const founderFocusList = founderFocusCandidates.slice(0, 3);

  const founderOperatingBrief = (() => {
    const nowMs = Date.now();
    const startOfTodayMs = new Date().setHours(0, 0, 0, 0);
    const brief = buildFounderOperatingBrief({
      focusCandidates: founderFocusCandidates.map(({ key, objectType, id, title, area, reason }) => ({
        key, objectType, id, title, area, reason,
      })),
      delegateItems: empireDecisionQueue.delegateItems.map(({ id, objectType, title, pillar, owner, whatIsChanging, whyItMatters }) => ({
        id, objectType, title, pillar, owner, whatIsChanging, whyItMatters,
      })),
      reviewItems: empireDecisionQueue.founderReviewQueue.map(({ kind, id, title, pillar, owner, reasonCategory, whyItMatters }) => ({
        kind, id, title, pillar, owner, reasonCategory, whyItMatters,
      })),
      actions: actionRecords.map((action) => ({
        id: action.id,
        title: action.actionTitle || action.title,
        area: getAreaText(action),
        owner: getActionOwnerDisplay(action, people),
        isActive: isActionActive(action),
        isWaiting: isActionWaiting(action),
        dueDate: action.dueDate,
      })),
      projects: projects.map((project) => ({
        id: project.id,
        title: project.projectName,
        area: project.area,
        owner: project.owner,
        isActive: isProjectActive(project),
        status: project.status,
        targetCompletionDate: project.targetCompletionDate,
      })),
      activeLeads: activeLeads.map(({ id, leadName, relatedPillar, owner, status, followUpDate }) => ({
        id, title: leadName, area: relatedPillar, owner, status, followUpDate,
      })),
      decisions: decisionRecords.map((decision) => ({
        id: decision.id,
        title: decision.decisionTitle || decision.title,
        area: getAreaText(decision),
        owner: decision.decisionMaker,
        isActive: isDecisionActive(decision),
        reviewDate: decision.reviewDate,
      })),
      opportunities: opportunityRecords.map((opportunity) => ({
        id: opportunity.id,
        title: opportunity.opportunityTitle || opportunity.title,
        area: getAreaText(opportunity),
        owner: opportunity.owner,
        status: opportunity.status,
        strategicFit: opportunity.strategicFit,
      })),
      nowMs,
      startOfTodayMs,
    });
    const attachOpen = (item: OperatingBriefDomainItem): OperatingBriefItem => ({
      ...item,
      onOpen: () => handleOpenAttentionRecord(item.objectType, item.id),
    });
    return {
      doNow: brief.doNow.map(attachOpen),
      delegate: brief.delegate.map((item): OperatingBriefItem => ({
        ...attachOpen(item),
        delegateAction: (personId: string) => handleDelegateItem(item.objectType, item.id, personId),
        eligibleDelegationPeople: getCapacityRankedDelegationPeopleForArea(item.area),
      })),
      decide: brief.decide.map(attachOpen),
      watch: brief.watch.map(attachOpen),
    };
  })();

  const todayBrief = buildOperatingPosture({
    focusCandidates: founderFocusCandidates.map(({ objectType, id, title, reason }) => ({ objectType, id, title, reason })),
    authorityItems: empireDecisionQueue.founderAuthorityItems.map(({ objectType, id }) => ({ objectType, id })),
    reviewsDue: decisionTrackRecord.reviewsDue.map(({ id }) => ({ id })),
    unassigned: {
      ownedActions: unassignedAccountability.ownedActions.map(({ id }) => ({ id })),
      activeProjects: unassignedAccountability.activeProjects.map(({ id }) => ({ id })),
      pipelineLeads: unassignedAccountability.pipelineLeads.map(({ id }) => ({ id })),
      unresolvedProblems: unassignedAccountability.unresolvedProblems.map(({ id }) => ({ id })),
      carriedCount: unassignedAccountability.carriedCount,
    },
    learningGaps: recurringProblemLearning.gaps.map(({ id }) => ({ id })),
    decisionsWithoutExecution: decisionsWithoutExecution.map(({ id }) => ({ id })),
    confidenceLimitations: strategicDataConfidence.limitations.map(({ severity }) => ({ severity })),
    personAttentionCounts: personAccountabilitySummaries.map(({ attentionCount }) => attentionCount),
    health: {
      delegationQualityLabel: organisationalHealth.delegationQuality.label,
      selfSufficiencyPct: organisationalHealth.selfSufficiencyPct,
      topOwnerShare: organisationalHealth.topOwnerShare,
    },
    operationalIndependencePct: operationalIndependence.operationalIndependencePct,
    delegation: {
      candidateCount: empireDecisionQueue.delegateItems.length,
      capacityCount: empireDecisionQueue.delegationCapacityNames.length,
      readinessGapCount: empireDecisionQueue.delegationReadinessGapNames.length,
    },
    staleRecords: staleRecords.map(({ objectType, id }) => ({ objectType, id })),
    capitalAttention: founderCapitalAttention.map(({ key }) => ({ key })),
    growth: {
      stalledOpportunities: growthAttention.stalledOpportunities.map(({ id }) => ({ id })),
      stalledLeads: growthAttention.stalledLeads.map(({ id }) => ({ id })),
      stalledQuoteValue: growthAttention.stalledQuoteValue,
      formattedStalledQuoteValue: growthAttention.stalledQuoteValue > 0
        ? formatFinanceAmount(growthAttention.stalledQuoteValue)
        : "",
      count: growthAttention.count,
    },
    clusters: correlationLayer.clusters.map((cluster) => ({
      recordKeys: cluster.records.map(({ recordKey }) => recordKey),
    })),
    signalled: new Map([...correlationLayer.signalled].map(([key, record]) => [
      key,
      { title: record.title, objectType: record.objectType, signals: [...record.signals] },
    ])),
  });

  const deskIsClear = founderFocusList.length === 0 && todayBrief.outstandingCount === 0;

  const attentionSnapshot: Record<string, string> = {};

  empireDecisionQueue.founderAuthorityItems.forEach((item) => {
    attentionSnapshot[`authority:${item.objectType}:${item.id}`] = "Founder authority";
  });
  decisionTrackRecord.reviewsDue.forEach((decision) => {
    attentionSnapshot[`review:Decision:${decision.id}`] = "Decision review";
  });
  const ownershipRecordKeys = new Set<string>();
  unassignedAccountability.ownedActions.forEach((action) => {
    attentionSnapshot[`ownership:Action:${action.id}`] = "Ownership gap";
    ownershipRecordKeys.add(`Action:${action.id}`);
  });
  unassignedAccountability.activeProjects.forEach((project) => {
    attentionSnapshot[`ownership:Project:${project.id}`] = "Ownership gap";
    ownershipRecordKeys.add(`Project:${project.id}`);
  });
  unassignedAccountability.pipelineLeads.forEach((lead) => {
    attentionSnapshot[`ownership:Lead:${lead.id}`] = "Ownership gap";
    ownershipRecordKeys.add(`Lead:${lead.id}`);
  });
  unassignedAccountability.unresolvedProblems.forEach((problem) => {
    attentionSnapshot[`ownership:Problem:${problem.id}`] = "Ownership gap";
    ownershipRecordKeys.add(`Problem:${problem.id}`);
  });
  decisionsWithoutExecution.forEach((decision) => {
    attentionSnapshot[`execution:Decision:${decision.id}`] = "Execution gap";
  });
  recurringProblemLearning.gaps.forEach((problem) => {
    attentionSnapshot[`learning:Problem:${problem.id}`] = "Recurring-learning gap";
  });
  staleRecords.forEach((item) => {
    const recordKey = `${item.objectType}:${item.id}`;
    if (ownershipRecordKeys.has(recordKey)) {
      return;
    }
    attentionSnapshot[`stale:${item.objectType}:${item.id}`] = "Stale record";
  });
  if (cashAttention.buffer) {
    attentionSnapshot["finance:cash-buffer"] = "Finance attention";
  }
  if (cashAttention.fundingGap) {
    attentionSnapshot["finance:funding-gap"] = "Finance attention";
  }
  cashAttention.overdueCommitments.forEach((item) => {
    attentionSnapshot[`finance:commitment:${item.id}`] = "Finance attention";
  });
  cashAttention.overdueExpectedIncome.forEach((item) => {
    attentionSnapshot[`finance:income:${item.id}`] = "Finance attention";
  });
  growthAttention.stalledOpportunities.forEach((item) => {
    attentionSnapshot[`growth:Opportunity:${item.id}`] = "Growth";
  });
  growthAttention.stalledLeads.forEach((item) => {
    if (ownershipRecordKeys.has(`Lead:${item.id}`)) {
      return;
    }
    attentionSnapshot[`growth:Lead:${item.id}`] = "Growth";
  });

  strategicDataConfidence.limitations
    .filter(
      (limitation) =>
        limitation.severity === "Blocker" ||
        limitation.severity === "Material",
    )
    .forEach((limitation) => {
      const objectType =
        limitation.key === "ownership"
          ? "People"
          : limitation.action?.objectType;

      const id =
        limitation.key === "ownership"
          ? "unassigned"
          : limitation.action?.id;

      if (!objectType || !id) {
        return;
      }

      attentionSnapshot[
        `confidence:${limitation.key}:${objectType}:${id}`
      ] = "Strategic data confidence";
    });

  const [clearedThisSession, setClearedThisSession] = useState<{ total: number; byCategory: Record<string, number> }>({ total: 0, byCategory: {} });
  const previousAttentionSnapshotRef = useRef<Record<string, string> | null>(null);
  const clearedKeysRef = useRef<Set<string>>(new Set());

  const attentionSnapshotJson = JSON.stringify(attentionSnapshot);

  useEffect(() => {
    if (!operatingDataLoaded) {
      previousAttentionSnapshotRef.current = null;
      return;
    }

    const currentSnapshot = JSON.parse(attentionSnapshotJson) as Record<string, string>;
    const currentKeys = new Set(Object.keys(currentSnapshot));

    if (previousAttentionSnapshotRef.current === null) {
      previousAttentionSnapshotRef.current = currentSnapshot;
      return;
    }

    const previousSnapshot = previousAttentionSnapshotRef.current;
    const previousKeys = new Set(Object.keys(previousSnapshot));
    const newlyCleared: Array<{ key: string; category: string }> = [];

    previousKeys.forEach((key) => {
      if (!currentKeys.has(key) && !clearedKeysRef.current.has(key)) {
        newlyCleared.push({ key, category: previousSnapshot[key] || "Founder authority" });
      }
    });

    if (newlyCleared.length > 0) {
      setClearedThisSession((current) => {
        const byCategory = { ...current.byCategory };
        newlyCleared.forEach(({ key, category }) => {
          clearedKeysRef.current.add(key);
          byCategory[category] = (byCategory[category] || 0) + 1;
        });
        return { total: current.total + newlyCleared.length, byCategory };
      });
    }

    previousAttentionSnapshotRef.current = currentSnapshot;
  }, [attentionSnapshotJson]);

  const clearedCategoryBreakdown = Object.entries(clearedThisSession.byCategory)
    .sort((a, b) => b[1] - a[1])
    .map(([category, count]) => `${count} ${category.toLowerCase()}`)
    .join(" • ");

  const todayProgressText = clearedThisSession.total === 0 && todayBrief.outstandingCount === 0
    ? "Nothing on the desk."
    : `Today: ${clearedThisSession.total} cleared • ${todayBrief.outstandingSituationCount} situation${todayBrief.outstandingSituationCount === 1 ? "" : "s"} outstanding${todayBrief.outstandingSituationCount !== todayBrief.outstandingCount ? ` across ${todayBrief.outstandingCount} records` : ""}${clearedCategoryBreakdown ? ` (${clearedCategoryBreakdown})` : ""}`;

  const todaySnapshotDate = new Date().toISOString().slice(0, 10);
  const cashIsConfigured = cashAmountsValid;
  const todaySnapshot: DailyPostureSnapshot = {
    date: todaySnapshotDate,
    focusCount: founderFocusCandidates.length,
    ownershipGapCount: todayBrief.ownershipGapCount,
    decisionReviewsDue: todayBrief.reviewDueCount,
    executionGapCount: todayBrief.executionGapCount,
    learningGapCount: todayBrief.learningGapCount,
    staleRecordCount: todayBrief.staleCount,
    financeAttentionCount: todayBrief.financeCount,
    growthStallCount: todayBrief.growthStallCount,
    outstandingCount: todayBrief.outstandingCount,
    availableOperatingCash: cashIsConfigured ? availableOperatingCash : null,
    delegationQualityPct: organisationalHealth.delegationScore,
    avgOpenDecisionDays: organisationalHealth.avgOpenDecisionDays,
    selfSufficiencyPct: organisationalHealth.selfSufficiencyPct,
    outstandingKeys: todayBrief.outstandingKeys,
    ...(icarusLoaded ? { icarusExposure: icarusIntelligence.exposureSnapshot } : {}),
  };

  const todaySnapshotJson = JSON.stringify(todaySnapshot);
  const snapshotsLoadedRef = useRef(false);

  useEffect(() => {
    if (!snapshotsLoadedRef.current) {
      snapshotsLoadedRef.current = true;
      return;
    }

    setDailyPostureSnapshots((current) => {
      const existingTodayIndex = current.findIndex((entry) => entry.date === todaySnapshotDate);

      if (existingTodayIndex >= 0) {
        const existing = current[existingTodayIndex];
        // Before Icarus hydrates, keep today's recorded exposure rather than erasing it.
        const replacement = todaySnapshot.icarusExposure === undefined && existing.icarusExposure !== undefined
          ? { ...todaySnapshot, icarusExposure: existing.icarusExposure }
          : todaySnapshot;
        if (JSON.stringify(existing) === JSON.stringify(replacement)) {
          return current;
        }
        const next = [...current];
        next[existingTodayIndex] = replacement;
        window.localStorage.setItem(DAILY_POSTURE_SNAPSHOTS_STORAGE_KEY, JSON.stringify(next));
        return next;
      }

      const next = [...current, todaySnapshot].sort((a, b) => a.date.localeCompare(b.date));
      window.localStorage.setItem(DAILY_POSTURE_SNAPSHOTS_STORAGE_KEY, JSON.stringify(next));
      return next;
    });
  }, [todaySnapshotJson, todaySnapshotDate]);

  const previousDaySnapshot = (() => {
    const earlier = dailyPostureSnapshots
      .filter((entry) => entry.date < todaySnapshotDate)
      .sort((a, b) => b.date.localeCompare(a.date));
    return earlier[0] || null;
  })();

  const healthTrend = (() => {
    if (!previousDaySnapshot) {
      return { delegation: null as string | null, latency: null as string | null, selfSufficiency: null as string | null };
    }

    const trendText = (current: number | null, previous: number | null | undefined, lowerIsBetter: boolean, unit: string) => {
      if (current === null || previous === null || previous === undefined || current === previous) {
        return null;
      }
      const improved = lowerIsBetter ? current < previous : current > previous;
      return `${current}${unit} ${improved ? "↑" : "↓"} vs ${previous}${unit} ${improved ? "(improving)" : "(worsening)"}`;
    };

    return {
      delegation: trendText(organisationalHealth.delegationScore, previousDaySnapshot.delegationQualityPct, false, ""),
      latency: trendText(organisationalHealth.avgOpenDecisionDays, previousDaySnapshot.avgOpenDecisionDays, true, "d"),
      selfSufficiency: trendText(organisationalHealth.selfSufficiencyPct, previousDaySnapshot.selfSufficiencyPct, false, "%"),
    };
  })();

  const postureChange = (() => {
    const currentKeys = new Map(todayBrief.outstandingKeys.map((item) => [item.key, item]));
    const previousKeys = new Map((previousDaySnapshot?.outstandingKeys || []).map((item) => [item.key, item]));

    const resolveTitle = (key: string, item?: { title: string; objectType: string; category: string }) => {
      if (item?.title && item.title !== key) {
        return item;
      }
      const signalled = correlationLayer.signalled.get(key);
      if (signalled) {
        return { title: signalled.title, objectType: signalled.objectType, category: [...signalled.signals].join(", ") };
      }

      const keyParts = key.split(":");
      const objectTypes = ["Action", "Decision", "Problem", "Opportunity", "Project", "Lead", "Lesson"];
      const objectTypeIndex = keyParts.findIndex((part) => objectTypes.includes(part));
      const objectType = objectTypeIndex >= 0 ? keyParts[objectTypeIndex] : item?.objectType || "Record";
      const recordId = objectTypeIndex >= 0 ? keyParts.slice(objectTypeIndex + 1).join(":") : "";
      const recordTitle = objectType === "Action"
        ? actionRecords.find((record) => record.id === recordId)?.actionTitle
        : objectType === "Decision"
          ? decisionRecords.find((record) => record.id === recordId)?.decisionTitle
          : objectType === "Problem"
            ? problemRecords.find((record) => record.id === recordId)?.problemStatement
            : objectType === "Opportunity"
              ? opportunityRecords.find((record) => record.id === recordId)?.opportunityTitle
              : objectType === "Project"
                ? projects.find((record) => record.id === recordId)?.projectName
                : objectType === "Lead"
                  ? leads.find((record) => record.id === recordId)?.leadName
                  : objectType === "Lesson"
                    ? lessonRecords.find((record) => record.id === recordId)?.lessonTitle
                    : undefined;

      return {
        title: recordTitle || `Resolved ${objectType.toLowerCase()} attention`,
        objectType,
        category: item?.category || "attention",
      };
    };

    const newSincePrevious = [...currentKeys.entries()]
      .filter(([key]) => !previousKeys.has(key))
      .map(([key, item]) => ({ key, ...resolveTitle(key, item) }));

    const resolvedSincePrevious = [...previousKeys.keys()]
      .filter((key) => !currentKeys.has(key))
      .map((key) => ({ key, ...resolveTitle(key, previousKeys.get(key)) }));

    const movedAgainst: Array<{ label: string; text: string }> = [];
    if (previousDaySnapshot) {
      const worsened = (label: string, currentValue: number, previousValue: number) => {
        if (currentValue > previousValue) {
          movedAgainst.push({ label, text: `${previousValue} → ${currentValue}` });
        }
      };
      worsened("Ownership gaps", todayBrief.ownershipGapCount, previousDaySnapshot.ownershipGapCount);
      worsened("Decision reviews", todayBrief.reviewDueCount, previousDaySnapshot.decisionReviewsDue);
      worsened("Execution gaps", todayBrief.executionGapCount, previousDaySnapshot.executionGapCount);
      worsened("Learning gaps", todayBrief.learningGapCount, previousDaySnapshot.learningGapCount);
      worsened("Stale records", todayBrief.staleCount, previousDaySnapshot.staleRecordCount);
      worsened("Finance attention", todayBrief.financeCount, previousDaySnapshot.financeAttentionCount);
      worsened("Growth stalls", todayBrief.growthStallCount, previousDaySnapshot.growthStallCount);

      if (todaySnapshot.availableOperatingCash !== null && previousDaySnapshot.availableOperatingCash !== null && todaySnapshot.availableOperatingCash < previousDaySnapshot.availableOperatingCash) {
        movedAgainst.push({ label: "Operating cash", text: `${formatFinanceAmount(previousDaySnapshot.availableOperatingCash)} → ${formatFinanceAmount(todaySnapshot.availableOperatingCash)}` });
      }
    }

    return {
      hasBaseline: previousDaySnapshot !== null,
      newSincePrevious,
      movedAgainst,
      resolvedSincePrevious,
    };
  })();

  const trendItems = (() => {
    if (!previousDaySnapshot) {
      return [] as Array<{ label: string; text: string; direction: "up" | "down" | "flat" }>;
    }

    const gapItem = (label: string, currentValue: number, previousValue: number) => {
      if (currentValue === previousValue) {
        return { label, text: `${currentValue} → unchanged`, direction: "flat" as const };
      }
      const improved = currentValue < previousValue;
      return {
        label,
        text: `${currentValue} ${improved ? "↓" : "↑"} from ${previousValue}`,
        direction: improved ? ("down" as const) : ("up" as const),
      };
    };

    const items = [
      gapItem("Ownership gaps", todayBrief.ownershipGapCount, previousDaySnapshot.ownershipGapCount),
      gapItem("Decision reviews", todayBrief.reviewDueCount, previousDaySnapshot.decisionReviewsDue),
      gapItem("Execution gaps", todayBrief.executionGapCount, previousDaySnapshot.executionGapCount),
      gapItem("Learning gaps", todayBrief.learningGapCount, previousDaySnapshot.learningGapCount),
      gapItem("Stale records", todayBrief.staleCount, previousDaySnapshot.staleRecordCount),
      gapItem("Finance attention", todayBrief.financeCount, previousDaySnapshot.financeAttentionCount),
      gapItem("Growth stalls", todayBrief.growthStallCount, previousDaySnapshot.growthStallCount),
    ];

    if (todaySnapshot.availableOperatingCash !== null && previousDaySnapshot.availableOperatingCash !== null) {
      const currentCash = todaySnapshot.availableOperatingCash;
      const previousCash = previousDaySnapshot.availableOperatingCash;
      if (currentCash === previousCash) {
        items.push({ label: "Operating cash", text: `${formatFinanceAmount(currentCash)} → unchanged`, direction: "flat" });
      } else {
        const improved = currentCash > previousCash;
        items.push({
          label: "Operating cash",
          text: `${formatFinanceAmount(currentCash)} ${improved ? "↑" : "↓"} from ${formatFinanceAmount(previousCash)}`,
          direction: improved ? "up" : "down",
        });
      }
    }

    return items;
  })();

  const sevenDayShape = (() => {
    const recent = [...dailyPostureSnapshots]
      .sort((a, b) => a.date.localeCompare(b.date))
      .slice(-7);
    if (recent.length === 0) {
      return "";
    }
    return recent.map((entry) => entry.outstandingCount).join(" → ");
  })();

  const founderOperatingReviewPolicy = buildFounderOperatingReview({
    todaySnapshotDate,
    snapshots: dailyPostureSnapshots,
    todayBrief: {
      ownershipGapCount: todayBrief.ownershipGapCount,
      reviewDueCount: todayBrief.reviewDueCount,
      executionGapCount: todayBrief.executionGapCount,
      learningGapCount: todayBrief.learningGapCount,
      staleCount: todayBrief.staleCount,
      financeCount: todayBrief.financeCount,
      growthStallCount: todayBrief.growthStallCount,
      outstandingKeys: todayBrief.outstandingKeys,
    },
    selfSufficiencyPct: organisationalHealth.selfSufficiencyPct,
    delegationQualityPct: organisationalHealth.delegationScore,
    cashIsConfigured,
    availableOperatingCash,
    topOwnerShare: organisationalHealth.topOwnerShare,
    delegateItemCount: empireDecisionQueue.delegateItems.length,
    unresolvedRecurring: recurringProblemLearning.unresolvedRecurring.map((problem) => ({
      id: problem.id,
      problemStatement: problem.problemStatement,
      title: problem.title,
      area: getAreaText(problem),
      frequency: problem.frequency,
      severity: problem.severity,
    })),
    convergentRisks: correlationLayer.convergentRisks.map((cluster) => ({
      clusterKey: cluster.clusterKey,
      title: cluster.title,
      categoryCount: cluster.categories.size,
      recordCount: cluster.recordCount,
      root: {
        id: cluster.records[0].id,
        objectType: cluster.records[0].objectType,
        area: cluster.records[0].area,
      },
      strategicRisks: icarusCorrelation.clusterContributions.get(cluster.clusterKey)?.assessments
        .map(({ assessmentId, outcome, exposure }) => ({ assessmentId, outcome, exposure })),
    })),
    focusCandidates: founderFocusCandidates.map(({ key, objectType, id, title, area, reason }) => ({
      key, objectType, id, title, area, reason,
    })),
    unassignedCarriedCount: unassignedAccountability.carriedCount,
    icarusExposure: icarusLoaded && todaySnapshot.icarusExposure
      ? {
        current: todaySnapshot.icarusExposure,
        assessmentStatuses: icarusIntelligence.assessmentStatuses,
      }
      : undefined,
    founderReviewQueue: empireDecisionQueue.founderReviewQueue.map((item) => ({
      kind: item.kind,
      id: item.id,
      title: item.title,
      pillar: item.pillar,
      reasonCategory: item.reasonCategory,
      whyItMatters: item.whyItMatters,
    })),
    watch: founderOperatingBrief.watch.map((item, sourceIndex) => ({
      id: item.id,
      objectType: item.objectType,
      title: item.title,
      area: item.area || "",
      why: item.why,
      sourceIndex,
    })),
  });
  const attachFounderOperatingReviewNavigation = (
    item: (typeof founderOperatingReviewPolicy.recurring)[number],
  ): RecurringReviewItem => {
    const { navigation, ...reviewItem } = item;
    if (navigation.type === "unassigned") {
      return {
        ...reviewItem,
        onOpen: () => {
          setActiveView("People");
          setSelectedAccountabilityKey("unassigned");
        },
      };
    }
    if (navigation.type === "watch") {
      return { ...reviewItem, onOpen: founderOperatingBrief.watch[navigation.index].onOpen };
    }
    return {
      ...reviewItem,
      onOpen: () => handleOpenAttentionRecord(navigation.objectType, navigation.id),
    };
  };
  const founderOperatingReview = {
    ...founderOperatingReviewPolicy,
    recurring: founderOperatingReviewPolicy.recurring.map(attachFounderOperatingReviewNavigation),
    next7Days: founderOperatingReviewPolicy.next7Days.map(attachFounderOperatingReviewNavigation),
  };

  const getFounderAttentionObjectiveForProject = (projectId: string) => strategicObjectives.find((objective) =>
    objective.status === "Active" && objective.founderAllocation === "Founder attention now" && objective.linkedProjectIds.includes(projectId));

  const founderBottleneckMap = (() => {
    const routineDelegateItems = empireDecisionQueue.delegateItems.filter((item) => item.objectType !== "Project" || !getFounderAttentionObjectiveForProject(item.id));
    // Track claims while projecting helper facts, preserving duplicate-record lookup
    // order and the original per-eligible-action overdue clock samples.
    const usedKeys = new Set(empireDecisionQueue.founderReviewQueue.map((item) => `${item.kind}:${item.id}`));
    const retainedProjects = projects.filter(isProjectActive).flatMap((project) => {
      if (!isFounderOwned(project.owner)) return [];
      const objective = getFounderAttentionObjectiveForProject(project.id);
      const key = `Project:${project.id}`;
      if (!objective || usedKeys.has(key)) return [];
      usedKeys.add(key);
      return [{ id: project.id, title: project.projectName, area: project.area, owner: project.owner, founderObjectiveTitle: objective.title }];
    });
    const opportunities = opportunityRecords
      .filter((opp) => opp.status === "Evaluating" && ["High", "Exceptional"].includes(opp.strategicFit))
      .flatMap((opp) => {
        const key = `Opportunity:${opp.id}`;
        if (usedKeys.has(key)) return [];
        const hasSettledDecision = decisionRecords.some((d) => d.relatedOpportunity === opp.id && ["Completed", "Reversed"].includes(d.decisionStatus));
        if (hasSettledDecision) return [];
        usedKeys.add(key);
        return [{
          id: opp.id, title: opp.opportunityTitle || opp.title, area: getAreaText(opp), owner: opp.owner,
          status: opp.status, strategicFit: opp.strategicFit, hasSettledDecision,
        }];
      });
    const executionDecisions = decisionsWithoutExecution.map(({ id, title, area, owner }) => ({ id, title, area, owner }));
    executionDecisions.forEach((decision) => usedKeys.add(`Decision:${decision.id}`));
    const blockedActions = actionRecords.filter((action) => isActionActive(action) && !isActionWaiting(action) && !isReleaseInterventionAction(action)).flatMap((action) => {
      const key = `Action:${action.id}`;
      if (usedKeys.has(key)) return [];
      const dependencyBlocker = getActionDependencyBlocker(action);
      const founderOwned = isFounderOwned(action.owner, action.ownerPersonId);
      const facts = {
        id: action.id, title: action.actionTitle || action.title,
        isBlocked: action.status === "Blocked", isFounderOwned: founderOwned,
        dependencyReason: dependencyBlocker?.reason ?? null,
      };
      if (!isFounderBottleneckBlockedAction(facts)) return [];
      usedKeys.add(key);
      return [{ ...facts, area: getAreaText(action), owner: getActionOwnerDisplay(action, people) }];
    });
    const overdueActions = actionRecords.filter((action) => isActionActive(action) && !isActionWaiting(action) && !isReleaseInterventionAction(action)).flatMap((action) => {
      const key = `Action:${action.id}`;
      if (usedKeys.has(key) || !isFounderOwned(action.owner, action.ownerPersonId)) return [];
      const isOverdue = action.dueDate && new Date(action.dueDate).getTime() < Date.now();
      if (!isOverdue) return [];
      usedKeys.add(key);
      return [{
        id: action.id, title: action.actionTitle || action.title, area: getAreaText(action),
        owner: getActionOwnerDisplay(action, people), dueDate: action.dueDate, isOverdue: true,
      }];
    });
    const executionProjects = projects.filter(isProjectActive).flatMap((project) => {
      const key = `Project:${project.id}`;
      if (usedKeys.has(key)) return [];
      const health = getEffectiveProjectHealth(project);
      const reviewDue = isProjectReviewDue(project);
      const reviewFuture = isProjectReviewFuture(project);
      const facts = { id: project.id, title: project.projectName, health, reviewDue, reviewFuture };
      if (!isFounderBottleneckExecutionProject(facts)) return [];
      usedKeys.add(key);
      return [{ ...facts, area: project.area, owner: project.owner, reviewNote: project.reviewNote, nextReviewDate: project.nextReviewDate }];
    });
    const convergentRisks = correlationLayer.convergentRisks.flatMap((cluster) => {
      if (usedKeys.has(cluster.clusterKey)) return [];
      const root = cluster.records[0];
      usedKeys.add(cluster.clusterKey);
      return [{
        clusterKey: cluster.clusterKey, title: cluster.title,
        root: { id: root.id, objectType: root.objectType, area: root.area || "" },
        categoryCount: cluster.categories.size, recordCount: cluster.recordCount,
      }];
    });
    const learningGaps = recurringProblemLearning.gaps.map(({ id, title, area, owner, severity, frequency }) => ({ id, title, area, owner, severity, frequency }));
    learningGaps.forEach((problem) => usedKeys.add(`Problem:${problem.id}`));
    const teamReadinessGaps = routineDelegateItems.length > 0
      && activeOperationalDelegationPeople.length > 0 && delegationReadyPeople.length === 0
      && !usedKeys.has("People:readiness-gap")
      ? teamDelegationReadinessGapPeople.map((person) => ({ name: person.name, missingFields: getDelegationReadinessMissingFields(person) }))
      : [];
    if (routineDelegateItems.length > 0 && activeOperationalDelegationPeople.length === 0) usedKeys.add("People:no-nonfounder");
    else if (teamReadinessGaps.length > 0) usedKeys.add("People:readiness-gap");
    const cofounderReadinessGaps = usedKeys.has("People:cofounder-readiness-gap") ? []
      : cofounderReadinessGapPeople.map((person) => ({ name: person.name, missingFields: getDelegationReadinessMissingFields(person) }));
    if (cofounderReadinessGaps.length > 0) usedKeys.add("People:cofounder-readiness-gap");
    let needsOwnershipReadinessGaps = false;
    const routineItems = routineDelegateItems.map((item) => {
      const key = `${item.objectType}:${item.id}`;
      const facts = { id: item.id, objectType: item.objectType, title: item.title, pillar: item.pillar, owner: item.owner };
      if (usedKeys.has(key)) return { ...facts, capacityRankedNames: [] };
      const capacityRankedNames = getCapacityRankedDelegationPeopleForArea(item.pillar).map((person) => person.name);
      if (capacityRankedNames.length === 0 && delegationReadyPeople.length === 0) needsOwnershipReadinessGaps = true;
      usedKeys.add(key);
      return { ...facts, capacityRankedNames };
    });
    const policy = buildFounderBottleneckMap({
      reviewItems: empireDecisionQueue.founderReviewQueue.map(({ id, kind, title, pillar, owner, reasonCategory, whyItMatters }) => ({
        id, kind, title, pillar, owner, reasonCategory, whyItMatters,
      })),
      retainedProjects, opportunities, decisionsWithoutExecution: executionDecisions,
      blockedActions, overdueActions, executionProjects, convergentRisks, learningGaps,
      routineDelegateItems: routineItems,
      activeOperationalPeopleCount: activeOperationalDelegationPeople.length,
      delegationReadyPeopleCount: delegationReadyPeople.length,
      teamReadinessGaps, cofounderReadinessGaps,
      delegationReadinessGaps: needsOwnershipReadinessGaps
        ? delegationReadinessGapPeople.map((person) => ({ name: person.name, missingFields: getDelegationReadinessMissingFields(person) }))
        : [],
    });
    return {
      summary: policy.summary,
      bottlenecks: policy.bottlenecks.map(({ openPeopleView, ...item }) => ({
        ...item,
        onOpen: openPeopleView
          ? () => setActiveView("People")
          : () => handleOpenAttentionRecord(item.objectType, item.id),
      })),
    };
  })();

  const founderExecutionReleaseSystem = (() => {
    const releaseCandidateInputs: ReleaseCandidateInput[] = [];
    const releaseActionHistory = actionRecords.map((action) => ({
      id: action.id,
      releaseSourceType: action.releaseSourceType,
      releaseSourceId: action.releaseSourceId,
      releaseIntent: action.releaseIntent,
      status: action.status,
    }));

    const authorityKeys = new Set([
  ...empireDecisionQueue.founderReviewQueue.map((item) => `${item.kind}:${item.id}`),
  ...empireDecisionQueue.founderAuthorityItems.map((item) => `${item.objectType}:${item.id}`),
]);


    const nowMs = Date.now();

    // Helper to add founder item safely with deduplication
    const processFounderItem = (
      objectType: "Action" | "Project" | "Lead" | "Problem",
      id: string,
      title: string,
      area: string,
      owner: string,
      status: string,
      dueDateValue: string | undefined,
      priorityOrSeverity: string | undefined,
      isBlocked: boolean,
      dependencyBlockerReason: string | null,
      earliestExecutableDateValue?: string,
      followUpDateValue?: string,
      isLegitimatelyWaiting = false,
    ) => {
      const recordKey = `${objectType}:${id}`;
      const founderAttentionObjective = objectType === "Project"
        ? getFounderAttentionObjectiveForProject(id)
        : undefined;
      const requiresExplicitProjectAuthority = objectType === "Project"
        && projects.find((project) => project.id === id)?.executionAuthority === "Founder Authority Required";
      const requiresAuthority = authorityKeys.has(recordKey) || Boolean(founderAttentionObjective) || requiresExplicitProjectAuthority;
      const areaDelegationReadyPeople = getDelegationReadyPeopleForArea(area);
      const capacityRankedDelegationPeople = getCapacityRankedDelegationPeopleForArea(area);
      releaseCandidateInputs.push({
        id,
        objectType,
        title,
        area,
        owner,
        status,
        dueDate: dueDateValue,
        priorityOrSeverity,
        isBlocked,
        dependencyBlockerReason,
        earliestExecutableDate: earliestExecutableDateValue,
        followUpDate: followUpDateValue,
        isLegitimatelyWaiting,
        requiresAuthority,
        hasFounderAttentionObjective: Boolean(founderAttentionObjective),
        founderAttentionObjectiveTitle: founderAttentionObjective?.title,
        areaDelegationReadyPeople: areaDelegationReadyPeople.map(({ id: personId, name, pillar }) => ({ id: personId, name, pillar })),
        capacityRankedDelegationPeople: capacityRankedDelegationPeople.map(({ id: personId, name, pillar }) => ({ id: personId, name, pillar })),
        activeOperationalDelegationPeopleCount: activeOperationalDelegationPeople.length,
        delegationReadyPeopleCount: delegationReadyPeople.length,
        delegationReadinessGapPeople: delegationReadinessGapPeople.map((person) => ({
          name: person.name,
          missingFields: getDelegationReadinessMissingFields(person),
        })),
        releaseActions: releaseActionHistory,
      });
    };

    // Scan Founder-owned Actions
    actionRecords.filter((action) => isActionActive(action) && !isReleaseInterventionAction(action)).forEach((action) => {
      if (isFounderOwned(action.owner, action.ownerPersonId)) {
        const dependencyBlocker = getActionDependencyBlocker(action);
        processFounderItem(
          "Action",
          action.id,
          action.actionTitle || action.title,
          getAreaText(action),
          getActionOwnerDisplay(action, people),
          action.status,
          action.dueDate,
          action.priority,
          action.status === "Blocked",
          dependencyBlocker ? dependencyBlocker.reason.replace("BLOCKED BY PROBLEM: ", "").replace("WAITING ON DECISION: ", "") : null,
          action.earliestExecutableDate,
          action.followUpDate,
          isActionWaiting(action),
        );
      }
    });

    // Scan Founder-owned Projects
    projects.filter(isProjectActive).forEach((project) => {
      if (isFounderOwned(project.owner)) {
        const projectHealth = getEffectiveProjectHealth(project);
        const isBlocked = project.status.trim().toLowerCase() === "blocked" || projectHealth === "Blocked";
        processFounderItem(
          "Project",
          project.id,
          project.projectName,
          project.area,
          project.owner || "Founder",
          project.status,
          project.targetCompletionDate,
          undefined,
          isBlocked,
          isBlocked ? "Project is blocked" : null,
          undefined,
          project.nextReviewDate,
          projectHealth === "Waiting",
        );
      }
    });

    // Scan Founder-owned Leads
    activeLeads.filter((lead) => !["Won", "Lost"].includes(lead.status)).forEach((lead) => {
      if (isFounderOwned(lead.owner)) {
        processFounderItem(
          "Lead",
          lead.id,
          lead.leadName,
          lead.relatedPillar,
          lead.owner || "Founder",
          lead.status,
          lead.followUpDate,
          undefined,
          false,
          null,
        );
      }
    });

    // Scan Founder-owned Problems
    problemRecords.filter(isProblemUnresolved).forEach((problem) => {
      if (isFounderOwned(problem.owner)) {
        processFounderItem(
          "Problem",
          problem.id,
          problem.problemStatement || problem.title,
          getAreaText(problem),
          problem.owner || "Founder",
          problem.problemStatus,
          undefined,
          problem.severity,
          false,
          null,
        );
      }
    });

    const releasePlan = buildExecutionReleasePlan(releaseCandidateInputs, nowMs);
    const items: ExecutionReleaseItem[] = releasePlan.items.map((recommendation) => ({
      ...recommendation,
      eligibleDelegationPeople: recommendation.eligibleDelegationPeople.flatMap((rankedPerson) => {
        const person = delegationReadyPeople.find((entry) => entry.id === rankedPerson.id);
        if (!person) return [];
        const summary = personAccountabilitySummaries.find((entry) => entry.person.id === person.id);
        return [{
          ...person,
          carriedCount: summary?.carriedCount ?? 0,
          attentionCount: summary?.attentionCount ?? 0,
        }];
      }),
      onOpen: () => handleOpenAttentionRecord(recommendation.objectType, recommendation.id),
      delegateAction: (personId: string) => handleDelegateItem(recommendation.objectType, recommendation.id, personId),
    }));
    return {
      summary: releasePlan.summary,
      items,
    };
  })();

  // Operational Next Move: when nothing requires intervention, what is the strongest currently
  // executable piece of work? Reuses founderExecutionReleaseSystem's release classification and
  // Command's own attention/founder-focus keys purely to exclude anything already surfaced there.
  const operationalNextMove = (() => {
    const attentionKeys = new Set(commandAttentionItemList.map((item) => `${item.objectType}:${item.id}`));
    founderFocusCandidates.forEach((item) => attentionKeys.add(`${item.objectType}:${item.id}`));

    const candidates: Array<OperationalNextMoveCandidate & { tier: number; score: number; sortDate: number }> = [];

    // An Opportunity's execution is treated as "already existing" once any Decision converted from it
    // (directly, or via a linked Action) has spun up real Actions/Projects — at that point the concrete
    // execution record is the real candidate, not the umbrella Opportunity.
    const opportunityHasLinkedExecution = (opportunityId: string) => {
      const linkedDecisionIds = decisionRecords.filter((decision) => decision.relatedOpportunity === opportunityId).map((decision) => decision.id);
      const hasDirectAction = actionRecords.some((action) => action.relatedOpportunity === opportunityId);
      const hasDecisionLinkedAction = actionRecords.some((action) => linkedDecisionIds.includes(action.relatedDecision));
      const hasDecisionLinkedProject = projects.some((project) => (project.relatedDecisionIds || []).some((id) => linkedDecisionIds.includes(id)));
      return hasDirectAction || hasDecisionLinkedAction || hasDecisionLinkedProject;
    };

    founderExecutionReleaseSystem.items
      .filter((item) => item.objectType === "Action" || item.objectType === "Project")
      .filter((item) => item.releaseAction === "Complete Personally" || item.releaseAction === "Monitor / Retain Temporarily")
      .forEach((item) => {
        const key = `${item.objectType}:${item.id}`;
        if (attentionKeys.has(key)) return;

        const action = item.objectType === "Action" ? actionRecords.find((record) => record.id === item.id) : undefined;
        const project = item.objectType === "Project" ? projects.find((record) => record.id === item.id) : undefined;
        if (!action && !project) return;

        // A Project only counts as a concrete, founder-executable body of work (not an umbrella) once it is
        // actually underway or already carries a tangible linked Action — otherwise there is no real next step in it.
        if (project) {
          const hasLinkedActiveAction = actionRecords.some((record) => isActionActive(record) && !isActionWaiting(record) && (project.relatedActionIds || []).includes(record.id));
          const isUnderway = project.status.trim().toLowerCase() === "in progress";
          if (!hasLinkedActiveAction && !isUnderway) return;
        }

        const reasons: string[] = [];
        let score = 0;

        if (action) {
          const priorityWeight = action.priority === "Critical" ? 6 : action.priority === "High" ? 4 : action.priority === "Medium" ? 2 : 0;
          if (priorityWeight > 0) {
            score += priorityWeight;
            reasons.push(`${action.priority} priority`);
          }

          if (projects.some((proj) => isProjectActive(proj) && (proj.relatedActionIds || []).includes(action.id))) {
            score += 2;
            reasons.push("Advances an active project");
          }

          if (getAreaText(action).trim().toLowerCase() === "marketing / growth") {
            score += 2;
            reasons.push("Growth / marketing relevant");
          }
        }

        if (project) {
          const linkedActionCount = (project.relatedActionIds || []).length;
          if (linkedActionCount > 0) {
            score += 2;
            reasons.push(`Carries ${linkedActionCount} linked active work item${linkedActionCount === 1 ? "" : "s"}`);
          }

          if ((project.area || "").trim().toLowerCase() === "marketing / growth") {
            score += 2;
            reasons.push("Growth / marketing relevant");
          }
        }

        if (item.releaseAction === "Complete Personally") {
          score += 3;
          reasons.push("Already identified as the founder's to complete personally");
        }

        const dueDateValue = action?.dueDate || project?.targetCompletionDate || "";
        const dueTimestamp = dueDateValue ? getDateValue(dueDateValue) : 0;
        if (dueTimestamp > 0) {
          score += 1;
          reasons.push(`Has a concrete target date (${formatCapturedAt(dueDateValue)})`);
        }

        reasons.push("Executable now — no blocker, no authority gate, no future start date");

        candidates.push({
          objectType: item.objectType as "Action" | "Project",
          id: item.id,
          title: item.title,
          area: item.area || "Unassigned",
          reasons,
          tier: item.objectType === "Action" ? 0 : 1,
          score,
          sortDate: dueTimestamp > 0 ? dueTimestamp : Number.POSITIVE_INFINITY,
          onOpen: item.onOpen,
        });
      });

    opportunityRecords
      .filter((opportunity) => opportunity.status === "Approved" && isFounderOwned(opportunity.owner))
      // Only a genuinely standalone, not-yet-broken-down Opportunity is itself "directly actionable";
      // once it has spawned real Decision/Action/Project execution, that concrete record is preferred instead.
      .filter((opportunity) => !opportunityHasLinkedExecution(opportunity.id))
      .forEach((opportunity) => {
        const key = `Opportunity:${opportunity.id}`;
        if (attentionKeys.has(key)) return;

        const reasons: string[] = [];
        let score = 3;
        reasons.push("Approved growth opportunity, ready to pursue");

        const fitWeight = opportunity.strategicFit === "Exceptional" ? 6 : opportunity.strategicFit === "High" ? 4 : opportunity.strategicFit === "Medium" ? 2 : 0;
        if (fitWeight > 0) {
          score += fitWeight;
          reasons.push(`${opportunity.strategicFit} strategic fit`);
        }

        const upside = parseOptionalFinanceAmount(opportunity.estimatedUpside);
        if (upside !== null && upside > 0) {
          score += upside >= 5000 ? 3 : upside >= 1000 ? 2 : 1;
          reasons.push(`Estimated upside ${formatFinanceAmount(upside)}`);
        }

        reasons.push("Executable now — approved, not blocked, no authority gate");

        candidates.push({
          objectType: "Opportunity",
          id: opportunity.id,
          title: opportunity.opportunityTitle || opportunity.title,
          area: getAreaText(opportunity) || "Unassigned",
          reasons,
          tier: 2,
          score,
          sortDate: Number.POSITIVE_INFINITY,
          onOpen: () => {
            setSelectedOpportunityId(opportunity.id);
            setOpportunityEditor(opportunity);
          },
        });
      });

    // Ready-for-first-contact Outreach prospects are grouped into a single commercial move —
    // never one recommendation per contact, and never treated as attention/overdue.
    const readyOutreachCheckMs = new Date().setHours(0, 0, 0, 0);
    const readyOutreachContacts = outreachContacts.filter(
      (contact) => isReadyForInitialOutreach(contact, readyOutreachCheckMs) && !attentionKeys.has(`Outreach:${contact.id}`),
    );
    if (readyOutreachContacts.length > 0) {
      const count = readyOutreachContacts.length;
      const countWeight = count >= 10 ? 3 : count >= 5 ? 2 : 1;

      candidates.push({
        objectType: "Outreach",
        id: "ready-for-initial-outreach",
        title: `Begin initial outreach to ${count} ready prospect${count === 1 ? "" : "s"}`,
        area: "Marketing / Growth",
        reasons: [`${count} prepared Outreach prospect${count === 1 ? " is" : "s are"} ready for first contact and no higher-ranked executable founder work is currently active`],
        tier: 1,
        score: countWeight + 2,
        sortDate: Number.POSITIVE_INFINITY,
        onOpen: () => {
          setActiveView("Outreach");
          setOutreachStatusFilter(READY_FOR_INITIAL_OUTREACH_FILTER);
        },
      });
    }

    const openOutreachContacts = outreachContacts.filter(
      (contact) => !isOutreachFollowUpExcluded(contact.status),
    );
    const openOutreachClassifications = openOutreachContacts.map((contact) => ({
      contact,
      classification: classifyOutreachFollowUp(contact, readyOutreachCheckMs),
    }));
    const hasDueOrOverdueOutreach = openOutreachClassifications.some(
      ({ classification }) => classification === "Due today" || classification === "Overdue",
    );
    const allOpenOutreachIsWaiting = openOutreachClassifications.every(({ contact, classification }) =>
      classification === "Upcoming" ||
      (contact.status === "Future Phone Follow-Up" && !contact.nextFollowUpDate),
    );
    const readyOutreachCheckDate = new Date(readyOutreachCheckMs);
    const startOfTomorrowMs = new Date(
      readyOutreachCheckDate.getFullYear(),
      readyOutreachCheckDate.getMonth(),
      readyOutreachCheckDate.getDate() + 1,
    ).getTime();
    const hasOutreachCreatedToday = outreachContacts.some((contact) => {
      const createdAtMs = new Date(contact.dateCreated).getTime();
      return !Number.isNaN(createdAtMs) && createdAtMs >= readyOutreachCheckMs && createdAtMs < startOfTomorrowMs;
    });

    if (
      readyOutreachContacts.length === 0 &&
      !hasDueOrOverdueOutreach &&
      openOutreachContacts.length > 0 &&
      allOpenOutreachIsWaiting &&
      !hasOutreachCreatedToday
    ) {
      candidates.push({
        objectType: "Outreach",
        id: "replenish-outreach-pipeline",
        title: "Replenish outreach pipeline",
        area: "Marketing / Growth",
        reasons: ["All open Outreach contacts are waiting on future follow-up or deliberately deferred, with no fresh prospects sourced today"],
        tier: 3,
        score: 0,
        sortDate: Number.POSITIVE_INFINITY,
        onOpen: () => {
          setActiveView("Outreach");
          setOutreachStatusFilter("All statuses");
        },
      });
    }

    // Tier first: concrete Actions, then concrete Projects/ready Outreach, then standalone Opportunities,
    // with pipeline replenishment retained as the final fallback.
    const [best] = [...candidates].sort((left, right) =>
      left.tier - right.tier ||
      right.score - left.score ||
      left.sortDate - right.sortDate ||
      left.title.localeCompare(right.title),
    );

    return { candidate: best ? { objectType: best.objectType, id: best.id, title: best.title, area: best.area, reasons: best.reasons, onOpen: best.onOpen } : null };
  })();

  const strategicFounderAllocation = (() => {
    const [selected] = strategicAssessments
      .filter(({ objective }) => objective.status === "Active" && objective.founderAllocation === "Founder attention now" && ["Now", "Next"].includes(objective.horizon) && strategicImportances.includes(objective.importance) && strategicPillars.includes(objective.pillar))
      .sort((left, right) =>
        strategicHorizons.indexOf(left.objective.horizon) - strategicHorizons.indexOf(right.objective.horizon)
        || strategicImportances.indexOf(left.objective.importance) - strategicImportances.indexOf(right.objective.importance)
        || Number(left.hasExecutablePath) - Number(right.hasExecutablePath)
        || left.objective.createdAt.localeCompare(right.objective.createdAt)
        || left.objective.title.localeCompare(right.objective.title));
    if (!selected) return { objective: null, reasons: [], divergence: null };
    const { objective, gaps } = selected;
    const reasons = [`${objective.horizon} horizon`, `${objective.importance.toLowerCase()} importance`, "explicitly allocated to founder attention"];
    if (gaps.length) reasons.push(gaps[0]);
    else if (selected.hasExecutablePath) reasons.push("linked execution is available");
    if (objective.whyItMatters.trim()) reasons.push(objective.whyItMatters.trim());

    const operational = operationalNextMove.candidate;
    const aligned = operational && (
      (operational.objectType === "Project" && objective.linkedProjectIds.includes(operational.id))
      || (operational.objectType === "Opportunity" && objective.linkedOpportunityIds.includes(operational.id))
      || (operational.objectType === "Action" && actionRecords.some((action) => action.id === operational.id && (
        objective.linkedDecisionIds.includes(action.relatedDecision)
        || selected.linkedProjects.some((project) => (project.relatedActionIds || []).includes(action.id))
      )))
    );
    const divergence = !operational ? null : aligned
      ? "The executable operational move advances this strategic objective."
      : `“${operational.title}” is executable now, but “${objective.title}” has ${objective.horizon.toLowerCase()}-horizon ${objective.importance.toLowerCase()} importance and is explicitly allocated to founder judgement${gaps.length ? `; ${gaps[0].toLowerCase()}` : "."}`;
    return { objective, reasons, divergence };
  })();
  const currentAppliedReview = strategicReviews.find((review) => review.status === "Applied") || null;

  const decisionExecutionControlNowMs = Date.now();
  const decisionExecutionControlFacts = buildDecisionExecutionControl({
    decisions: decisionRecords.map((decision) => ({
      id: decision.id,
      title: decision.title,
      decisionTitle: decision.decisionTitle,
      status: decision.decisionStatus,
      riskLevel: decision.riskLevel,
      reviewDate: decision.reviewDate,
      reviewDue: isDecisionActive(decision) && isDecisionReviewDue(decision),
      outcomeRating: decision.outcomeRating,
      actualOutcome: decision.actualOutcome,
      decisionMaker: decision.decisionMaker,
      area: getAreaText(decision) || "Unassigned",
    })),
    actions: actionRecords.map((action) => ({
      id: action.id,
      relatedDecision: action.relatedDecision,
      status: action.status,
      dueDate: action.dueDate,
      title: action.title,
      actionTitle: action.actionTitle,
      hasValidOwner: getValidActiveOwnerKey(action.owner, action.ownerPersonId) !== null,
    })),
    projects: projects.map((project) => ({
      id: project.id,
      status: project.status,
      relatedDecisionIds: project.relatedDecisionIds,
      relatedActionIds: project.relatedActionIds,
      targetCompletionDate: project.targetCompletionDate,
      projectName: project.projectName,
      hasValidOwner: getValidActiveOwnerKey(project.owner, undefined) !== null,
    })),
    delegateItems: empireDecisionQueue.delegateItems.map(({ objectType, id }) => ({ objectType, id })),
    nowMs: decisionExecutionControlNowMs,
  });
  const decisionControlItemsByFact = new Map<DecisionExecutionControlItem, DecisionControlItem>();
  const withDecisionNavigation = (item: DecisionExecutionControlItem): DecisionControlItem => {
    const existing = decisionControlItemsByFact.get(item);
    if (existing) return existing;
    const withNavigation = {
      ...item,
      onOpen: () => handleOpenAttentionRecord("Decision", item.id),
    };
    decisionControlItemsByFact.set(item, withNavigation);
    return withNavigation;
  };
  const decisionControlLayer = {
    summary: decisionExecutionControlFacts.summary,
    items: decisionExecutionControlFacts.items.map(withDecisionNavigation),
    onTrackItems: decisionExecutionControlFacts.onTrackItems.map(withDecisionNavigation),
    learningIncompleteItems: decisionExecutionControlFacts.learningIncompleteItems.map(withDecisionNavigation),
  };

  const getAttentionGroup = (item: AttentionItem) => {
    const isBlockedOrWaiting = item.reasons.some((reason) =>
      reason === "BLOCKED PROJECT" || (item.objectType !== "Project" && reason === "BLOCKED") || reason.startsWith("BLOCKED BY PROBLEM:") || reason.startsWith("WAITING ON DECISION:"),
    );

    if (isBlockedOrWaiting) {
      return "Blocked / Waiting";
    }

    if ((item.objectType === "Action" && item.reasons.some((reason) => reason.startsWith("OVERDUE BY "))) || (item.objectType === "Project" && item.reasons.includes("OVERDUE PROJECT")) || (item.objectType === "Outreach" && item.reasons.some((reason) => reason.startsWith("OVERDUE BY ")))) {
      return "Urgent / Overdue";
    }

    if (item.objectType === "Problem" && item.reasons.some((reason) => reason.includes("SEVERITY")) && item.attentionRank === 3) {
      return "Urgent / Overdue";
    }

    if (item.objectType === "Decision" && item.reasons.includes("REVIEW DUE")) {
      return "Urgent / Overdue";
    }

    if (item.objectType === "Problem") {
      return "Problems";
    }

    if (item.objectType === "Action") {
      return "Actions";
    }

    if (item.objectType === "Project") {
      return "Projects";
    }

    if (item.objectType === "Opportunity") {
      return "Opportunities";
    }

    if (item.objectType === "Icarus") {
      return "Strategic Risk";
    }

    if (item.objectType === "Lead") {
      return "Other Attention";
    }

    if (item.objectType === "Finance") {
      return "Other Attention";
    }

    if (item.objectType === "Outreach") {
      return "Outreach";
    }

    return "Other Attention";
  };
  const commandAttentionGroups = ["Blocked / Waiting", "Urgent / Overdue", "Strategic Risk", "Problems", "Actions", "Projects", "Opportunities", "Outreach", "Other Attention"]
    .map((label) => ({
      label,
      items: commandAttentionItemList.filter((item) => item.objectType !== "Finance" && getAttentionGroup(item) === label),
    }))
    .filter((group) => group.items.length > 0);
  const commandAttentionItems = commandAttentionItemList.filter((item) => item.objectType !== "Finance").length;
  const executiveAttentionRecordKeys = new Set(todayBrief.outstandingKeys.map((item) => item.key));
  const executiveAttentionItems = todayBrief.outstandingCount;
  const projectAttentionCount = new Set(
    commandAttentionGroups.flatMap((group) => group.items)
      .filter((item) => item.objectType === "Project")
      .map((item) => item.id),
  ).size;
  const attentionSummaryItems = commandAttentionGroups
    .map((group) => ({
      label: group.label,
      count: group.items.filter((item) => executiveAttentionRecordKeys.has(`${item.objectType}:${item.id}`)).length,
    }))
    .filter((group) => group.count > 0);
  const getAttentionSummaryLabel = (label: string, count: number) => {
    if (count !== 1) {
      return label;
    }

    return label
      .replace("Blocked / Waiting", "Blocked / Waiting item")
      .replace("Problems", "Problem")
      .replace("Actions", "Action")
      .replace("Projects", "Project")
      .replace("Opportunities", "Opportunity")
      .replace("Decisions", "Decision")
      .replace("Other Attention", "Other attention item");
  };
  const overdueActionCount = actionRecords.filter((action) => {
    if (!isActionActive(action) || isActionWaiting(action) || !action.dueDate) {
      return false;
    }

    const dueDate = new Date(action.dueDate);
    return !Number.isNaN(dueDate.getTime()) && dueDate.getTime() < Date.now();
  }).length;
  const decisionsDueForReviewCount = decisionRecords.filter((decision) => {
    if (!isDecisionActive(decision) || !decision.reviewDate) {
      return false;
    }

    const reviewDate = new Date(decision.reviewDate);
    return !Number.isNaN(reviewDate.getTime()) && reviewDate.getTime() <= Date.now();
  }).length;
  const criticalHighProblemCount = problemRecords.filter((problem) =>
    isProblemUnresolved(problem) &&
    (problem.severity === "Critical" || problem.severity === "High"),
  ).length;

  const commandRecordGroups: CommandRecordGroup[] = [
    {
      label: "Problems",
      records: problemRecords.map((problem) => ({
        id: problem.id,
        objectType: "Problem",
        title: problem.problemStatement || problem.title,
        searchText: `${problem.problemStatement || problem.title} ${problem.impact} ${problem.rootCause}`,
        createdAt: problem.createdAt,
        operationalDate: "",
        owner: problem.owner || "Unassigned",
        status: problem.problemStatus,
        area: getAreaText(problem),
        sourceCaptureId: problem.sourceCaptureId,
        onOpen: () => {
          setSelectedProblemId(problem.id);
          setProblemEditor(problem);
        },
      })),
    },
    {
      label: "Actions",
      records: actionRecords.map((action) => ({
        id: action.id,
        objectType: "Action",
        title: action.actionTitle || action.title,
        searchText: `${action.actionTitle || action.title} ${action.description}`,
        createdAt: action.createdAt,
        operationalDate: action.dueDate,
        owner: getActionOwnerDisplay(action, people),
        status: action.status,
        area: getAreaText(action),
        sourceCaptureId: action.sourceCaptureId,
        onOpen: () => {
          setSelectedActionId(action.id);
          setActionEditor(action);
        },
      })),
    },
    {
      label: "Decisions",
      records: decisionRecords.map((decision) => ({
        id: decision.id,
        objectType: "Decision",
        title: decision.decisionTitle || decision.title,
        searchText: `${decision.decisionTitle || decision.title} ${decision.decisionStatement} ${decision.context} ${decision.reasoning}`,
        createdAt: decision.createdAt,
        operationalDate: decision.reviewDate,
        owner: decision.decisionMaker || "Unassigned",
        status: decision.decisionStatus,
        area: getAreaText(decision),
        sourceCaptureId: decision.sourceCaptureId,
        onOpen: () => {
          setSelectedDecisionId(decision.id);
          setDecisionEditor(decision);
        },
      })),
    },
    {
      label: "Opportunities",
      records: opportunityRecords.map((opportunity) => ({
        id: opportunity.id,
        objectType: "Opportunity",
        title: opportunity.opportunityTitle || opportunity.title,
        searchText: `${opportunity.opportunityTitle || opportunity.title} ${opportunity.description} ${opportunity.evidence}`,
        createdAt: opportunity.createdAt,
        operationalDate: "",
        owner: opportunity.owner || "Unassigned",
        status: opportunity.status,
        area: getAreaText(opportunity),
        sourceCaptureId: opportunity.sourceCaptureId,
        onOpen: () => {
          setSelectedOpportunityId(opportunity.id);
          setOpportunityEditor(opportunity);
        },
      })),
    },
    {
      label: "Projects",
      records: projects.map((project) => ({
        id: project.id,
        objectType: "Project",
        title: project.projectName,
        searchText: `${project.projectName} ${project.owner} ${project.area} ${project.status}`,
        createdAt: "",
        startDate: project.startDate,
        operationalDate: project.targetCompletionDate,
        owner: project.owner || "Unassigned",
        status: project.status || "No status",
        area: project.area,
        sourceCaptureId: project.sourceCaptureId || "",
        onOpen: () => handleProjectEditOpen(project),
      })),
    },
    {
      label: "Lessons",
      records: lessonRecords.map((lesson) => ({
        id: lesson.id,
        objectType: "Lesson",
        title: lesson.lessonTitle || lesson.title,
        searchText: `${lesson.lessonTitle || lesson.title} ${lesson.description} ${lesson.whyItMatters} ${lesson.recommendedChange}`,
        createdAt: lesson.createdAt,
        operationalDate: "",
        owner: lesson.owner || "Unassigned",
        status: lesson.status,
        area: getAreaText(lesson),
        sourceCaptureId: lesson.sourceCaptureId,
        onOpen: () => {
          setSelectedLessonId(lesson.id);
          setLessonEditor(lesson);
        },
      })),
    },
    {
      label: "Systems",
      records: systemRecords.map((system) => ({
        id: system.id,
        objectType: "System",
        title: system.systemName || system.title,
        searchText: `${system.systemName || system.title} ${system.purpose} ${system.process} ${system.outputs}`,
        createdAt: system.createdAt,
        operationalDate: "",
        owner: system.owner || "Unassigned",
        status: system.status,
        area: system.area,
        sourceCaptureId: system.sourceCaptureId,
        onOpen: () => {
          setSelectedSystemId(system.id);
          setSystemEditor(system);
        },
      })),
    },
    {
      label: "SOPs",
      records: sopRecords.map((sop) => ({
        id: sop.id,
        objectType: "SOP",
        title: sop.sopTitle || sop.title,
        searchText: `${sop.sopTitle || sop.title} ${sop.purpose} ${sop.procedure} ${sop.qualityStandard}`,
        createdAt: sop.createdAt,
        operationalDate: "",
        owner: sop.owner || "Unassigned",
        status: sop.status,
        area: systemRecords.find((system) => system.id === sop.relatedSystem)?.area || sop.relatedArea?.trim() || "",
        sourceCaptureId: sop.sourceCaptureId,
        onOpen: () => {
          setSelectedSopId(sop.id);
          setSopEditor(sop);
        },
      })),
    },
  ];

  const getCaptureLineage = (captureId?: string) => {
    if (!captureId) {
      return [] as RelatedRecordItem[];
    }

    const capture = captures.find((item) => item.id === captureId);
    if (!capture) {
      return [] as RelatedRecordItem[];
    }

    return [{
      label: "Capture",
      title: capture.title,
      id: capture.id,
    }];
  };

  const handleFieldChange = (field: keyof CaptureFormValues, value: string) => {
    setFormValues((currentValues) => ({
      ...currentValues,
      [field]: value,
    }));
  };

  const handleSubmit = (event: FormEvent<HTMLFormElement>) => {
    event.preventDefault();

    const trimmedTitle = formValues.title.trim();
    const trimmedNote = formValues.rawNote.trim();

    if (!trimmedTitle || !trimmedNote) {
      setFeedback({
        type: "error",
        message: "Title and raw note are required before saving a capture.",
      });
      return;
    }

    const newCapture: CaptureRecord = {
      id: generateCaptureId(),
      title: trimmedTitle,
      rawNote: trimmedNote,
      initialType: formValues.initialType,
      relatedArea: formValues.relatedArea,
      importance: formValues.importance,
      status: "New",
      capturedAt: new Date().toISOString(),
      reviewOutcome: null,
      reviewedAt: null,
    };

    setCaptures((currentCaptures) => [newCapture, ...currentCaptures]);
    setFormValues(defaultFormValues);
    setFeedback({
      type: "success",
      message: "Capture saved successfully.",
    });
  };

  const handleReview = (capture: CaptureRecord) => {
    if (capture.reviewOutcome) {
      setSelectedCaptureId(null);
      setFeedback({
        type: "success",
        message: `This capture was already reviewed as ${capture.reviewOutcome}.`,
      });
      return;
    }

    setSelectedCaptureId(capture.id);
    setSelectedOutcome("Keep as Capture");
    setProjectConversionDraft({
      ...defaultProjectConversionDraft,
      projectName: capture.title,
      area: sharedAreaOptions.includes(capture.relatedArea as (typeof sharedAreaOptions)[number])
        ? capture.relatedArea
        : defaultProjectConversionDraft.area,
    });
  };

  const handleReviewSubmit = () => {
    if (!selectedCaptureId || convertingCaptureIdsRef.current.has(selectedCaptureId)) {
      return;
    }

    const capture = captures.find((item) => item.id === selectedCaptureId);

    const existingProject = projects.find((project) => project.sourceCaptureId === selectedCaptureId);
    if (!capture || capture.reviewOutcome || existingProject) {
      setSelectedCaptureId(null);
      if (existingProject) {
        setFeedback({ type: "success", message: "This capture has already been converted to a Project." });
      }
      return;
    }

    if (selectedOutcome === "Convert to Project" && !projectConversionDraft.projectName.trim()) {
      setFeedback({ type: "error", message: "Project title is required before conversion." });
      return;
    }

    convertingCaptureIdsRef.current.add(selectedCaptureId);

    const reviewDate = new Date().toISOString();
    const nextStatus = getStatusFromOutcome(selectedOutcome);
    const outcomeLabel = formatReviewOutcome(selectedOutcome) ?? "Capture";

    const updatedCapture: CaptureRecord = {
      ...capture,
      status: nextStatus,
      reviewOutcome: selectedOutcome,
      reviewedAt: reviewDate,
    };

    const nextCaptureList = captures.map((item) =>
      item.id === selectedCaptureId ? updatedCapture : item,
    );

    setCaptures(nextCaptureList);

    if (selectedOutcome === "Convert to Project") {
      const selectedOwner = people.find((person) =>
        person.status === "Active" && person.name === projectConversionDraft.owner,
      );
      const selectedArea = sharedAreaOptions.includes(projectConversionDraft.area as (typeof sharedAreaOptions)[number])
        ? projectConversionDraft.area
        : capture.relatedArea;
      const selectedStatus = projectStatusOptions.includes(projectConversionDraft.status as (typeof projectStatusOptions)[number])
        ? projectConversionDraft.status
        : defaultProjectForm.status;
      const project: ProjectRecord = {
        ...defaultProjectForm,
        id: generateProjectId(),
        projectName: projectConversionDraft.projectName.trim(),
        owner: selectedOwner?.name || "",
        area: sharedAreaOptions.includes(selectedArea as (typeof sharedAreaOptions)[number])
          ? selectedArea
          : defaultProjectForm.area,
        targetCompletionDate: projectConversionDraft.targetCompletionDate,
        status: selectedStatus,
        sourceCaptureId: capture.id,
        title: capture.title,
        originalRawNote: capture.rawNote,
        createdAt: reviewDate,
      };

      setProjects((currentProjects) =>
        currentProjects.some((currentProject) => currentProject.sourceCaptureId === capture.id)
          ? currentProjects
          : [project, ...currentProjects],
      );
    }

    if (selectedOutcome !== "Keep as Capture" && selectedOutcome !== "Close" && selectedOutcome !== "Convert to Project") {
      const conversion: CaptureConversionRecord = {
        id: generateConversionId(),
        sourceCaptureId: capture.id,
        targetType: selectedOutcome,
        createdAt: reviewDate,
        title: capture.title,
        originalRawNote: capture.rawNote,
        relatedArea: capture.relatedArea,
        importance: capture.importance,
        status: nextStatus,
      };

      if (selectedOutcome === "Convert to Problem") {
        const problemDefaults = normalizeProblemRecord(conversion);
        Object.assign(conversion, problemDefaults);
      }

      if (selectedOutcome === "Convert to Decision") {
        const decisionDefaults = normalizeDecisionRecord(conversion);
        Object.assign(conversion, decisionDefaults);
      }

      if (selectedOutcome === "Convert to Opportunity") {
        const opportunityDefaults = normalizeOpportunityRecord(conversion);
        Object.assign(conversion, opportunityDefaults);
      }

      if (selectedOutcome === "Convert to Lesson") {
        const lessonDefaults = normalizeLessonRecord(conversion);
        Object.assign(conversion, lessonDefaults);
      }

      if (selectedOutcome === "Convert to System") {
        const systemDefaults = normalizeSystemRecord(conversion);
        Object.assign(conversion, systemDefaults);
      }

      setConversions((currentConversions) => [conversion, ...currentConversions]);
    }

    setSelectedCaptureId(null);
    convertingCaptureIdsRef.current.delete(capture.id);
    setFeedback({
      type: "success",
      message: selectedOutcome === "Close"
        ? "Capture closed and retained in the record."
        : selectedOutcome === "Keep as Capture"
          ? "Capture reviewed and kept as a capture."
          : `Capture converted to ${outcomeLabel}.`,
    });
  };

  const applyOwnershipChangeWithDelegationIntegrity = ({
    objectType,
    objectId,
    title,
    area,
    previousOwner,
    previousOwnerPersonId,
    newOwner,
    newOwnerPersonId,
    handoffContext,
    applyOwnershipChange,
  }: {
    objectType: DelegationHandoffRecord["objectType"];
    objectId: string;
    title: string;
    area: string;
    previousOwner: string;
    previousOwnerPersonId?: string;
    newOwner: string;
    newOwnerPersonId?: string;
    handoffContext: string;
    applyOwnershipChange: () => void;
  }) => {
    const previousOwnerName = previousOwner.trim() || "Unassigned";
    const newOwnerName = newOwner.trim() || "Unassigned";
    const previousOwnerPerson = previousOwnerPersonId
      ? orderedPeople.find((person) => person.id === previousOwnerPersonId)
      : orderedPeople.find((person) => person.status === "Active" && person.name.trim().toLowerCase() === previousOwnerName.toLowerCase());
    const ownerChanged = previousOwnerPersonId && newOwnerPersonId
      ? previousOwnerPersonId !== newOwnerPersonId
      : previousOwnerName.toLowerCase() !== newOwnerName.toLowerCase();

    if (!ownerChanged || newOwnerName.toLowerCase() === "unassigned" || isFounderOwned(newOwnerName, newOwnerPersonId)) {
      applyOwnershipChange();
      return true;
    }

    const destinationPerson = delegationReadyPeople.find((person) =>
      newOwnerPersonId
        ? person.id === newOwnerPersonId
        : person.name.trim().toLowerCase() === newOwnerName.toLowerCase(),
    );
    const isAreaEligible = destinationPerson
      ? getDelegationReadyPeopleForArea(area).some((person) => person.id === destinationPerson.id)
      : false;

    if (!destinationPerson || !isAreaEligible) {
      setFeedback({
        type: "error",
        message: destinationPerson
          ? `Choose a delegation-ready owner assigned to ${area || "this work item's area"}.`
          : "Choose an active delegation-ready non-founder owner.",
      });
      return false;
    }

    applyOwnershipChange();
    const transferredAt = new Date().toISOString();
    const reviewDate = new Date(transferredAt);
    reviewDate.setDate(reviewDate.getDate() + 14);
    setDelegationHandoffs((currentHandoffs) => {
      const activeExistingHandoff = currentHandoffs.find((handoff) =>
        handoff.objectType === objectType
        && handoff.objectId === objectId
        && handoff.newOwnerPersonId === destinationPerson.id
        && handoff.status !== "Completed"
        && handoff.status !== "Cancelled",
      );

      if (activeExistingHandoff) return currentHandoffs;

      return [
        ...currentHandoffs,
        {
        id: `handoff-${transferredAt}-${objectType}-${objectId}`,
        objectType,
        objectId,
        title: title || "Untitled work item",
        area: area || "Unassigned",
        previousOwner: previousOwnerName,
        previousOwnerPersonId: previousOwnerPerson?.id || previousOwnerPersonId,
        newOwner: destinationPerson.name,
        newOwnerPersonId: destinationPerson.id,
        delegatedBy: previousOwnerPerson?.name || previousOwnerName,
        delegatedByPersonId: previousOwnerPerson?.id || previousOwnerPersonId,
        transferredAt,
        handoffContext,
        handoffReason: handoffContext,
        reviewDate: reviewDate.toISOString().slice(0, 10),
        status: "Healthy",
        outcomeLesson: "",
      },
      ];
    });
    return true;
  };

  const handleProblemEditOpen = (problem: ProblemRecord) => {
    setSelectedProblemId(problem.id);
    setProblemEditor(problem);
  };

  const handleProblemEditorChange = (
    field: keyof Omit<ProblemRecord, "id" | "sourceCaptureId" | "targetType" | "createdAt" | "title" | "originalRawNote" | "relatedArea" | "importance" | "status">,
    value: string,
  ) => {
    if (!problemEditor) {
      return;
    }

    setProblemEditor({
      ...problemEditor,
      [field]: value,
    });
  };

  const handleProblemSave = () => {
    if (!selectedProblemId || !problemEditor) {
      return;
    }

    const updatedProblem = normalizeProblemRecord({
      ...problemEditor,
      status: problemEditor.problemStatus,
    });
    const persistedProblem = problemRecords.find((problem) => problem.id === selectedProblemId);
    const applySave = () => setConversions((currentConversions) =>
      currentConversions.map((conversion) =>
        conversion.id === selectedProblemId ? updatedProblem : conversion,
      ),
    );
    const saveSucceeded = persistedProblem
      ? applyOwnershipChangeWithDelegationIntegrity({
          objectType: "Problem",
          objectId: updatedProblem.id,
          title: updatedProblem.problemStatement || updatedProblem.title,
          area: getAreaText(updatedProblem),
          previousOwner: persistedProblem.owner,
          newOwner: updatedProblem.owner,
          handoffContext: updatedProblem.impact.trim() || updatedProblem.problemStatement,
          applyOwnershipChange: applySave,
        })
      : (applySave(), true);

    if (!saveSucceeded) return;

    setSelectedProblemId(null);
    setProblemEditor(null);
    setFeedback({
      type: "success",
      message: "Problem details saved.",
    });
  };

  const handleActionEditOpen = (action: ActionRecord) => {
    setSelectedActionId(action.id);
    setActionEditor(action);
  };

  const handleCreateReleaseAction = (item: ExecutionReleaseItem) => {
    if (item.releaseAction !== "Prepare to Delegate" && item.releaseAction !== "Unblock First") {
      return;
    }

    const existingAction = actionRecords.find((action) =>
      action.releaseSourceType === item.objectType
      && action.releaseSourceId === item.id
      && action.releaseIntent === item.releaseAction
      && isActionActive(action)
    );

    if (existingAction) {
      handleActionEditOpen(existingAction);
      setFeedback({ type: "success", message: "An active release action already exists." });
      return;
    }

    const createdAt = new Date();
    const dueDate = new Date(createdAt);
    dueDate.setDate(dueDate.getDate() + 7);
    const actionTitle = item.releaseAction === "Prepare to Delegate"
      ? `Prepare delegation capacity for ${item.area || "this area"}`
      : `Unblock ${item.area || "this area"} execution`;
    const createdAction = {
      ...normalizeActionRecord({
      id: generateConversionId(),
      sourceCaptureId: "",
      targetType: "Convert to Action",
      createdAt: createdAt.toISOString(),
      title: actionTitle,
      originalRawNote: item.why,
      relatedArea: item.area || "",
      importance: "High",
      status: "Open",
      actionTitle,
      actionDescription: `Founder Release System intervention for ${item.objectType}: ${item.title}\n\nWhy: ${item.why}\n\nRelease path: ${item.releasePath}`,
      createdBy: founderPerson?.name || "",
      createdDate: createdAt.toISOString(),
      dueDate: dueDate.toISOString(),
      priority: "High",
      relatedProblem: item.objectType === "Problem" ? item.id : "",
      relatedDecision: "",
      relatedCapture: "",
      relatedPillar: item.area || "",
      completionEvidence: "",
      completionDate: "",
      owner: founderPerson?.name || "",
      releaseSourceType: item.objectType,
      releaseSourceId: item.id,
      releaseIntent: item.releaseAction,
      }),
      ownerPersonId: founderPerson?.id,
    };

    setConversions((currentConversions) => [createdAction, ...currentConversions]);
    handleActionEditOpen(createdAction);
    setFeedback({ type: "success", message: "Release action created." });
  };

  const handleUpdateDelegationHandoff = (
    handoffId: string,
    updates: DelegationHandoffUpdate,
  ) => {
    const statusWasUpdated = Object.prototype.hasOwnProperty.call(updates, "status");
    setDelegationHandoffs((currentHandoffs) =>
      currentHandoffs.map((handoff) =>
        handoff.id === handoffId
          ? {
              ...handoff,
              ...updates,
              status: statusWasUpdated && updates.status && ["Healthy", "At risk", "Completed", "Cancelled"].includes(updates.status)
                ? updates.status
                : statusWasUpdated && updates.status === undefined
                  ? undefined
                  : handoff.status,
            }
          : handoff,
      ),
    );
  };

