                      item === "Problems" ||
                      item === "Opportunities" ||
                      item === "Actions" ||
                      item === "Decisions" ||
                      item === "Lessons" ||
                      item === "Projects" ||
                      item === "Systems" ||
                      item === "SOPs" ||
                      item === "Leads" ||
                      item === "Finance" ||
                      item === "Metrics" ||
                      item === "Pillars" ||
                      item === "People"
